insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f0000000-0000-0000-0000-000000000001', 'mrcp1', 'fb615642-574d-47d5-9c8a-f0e9539aaee5',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f0000000-0000-0000-0000-000000000001', 'A', 'Metformin', true, 'Correct. Metformin is first-line pharmacological therapy for type 2 diabetes, alongside lifestyle measures, unless contraindicated (e.g. significant renal impairment), as it improves glycaemic control without causing hypoglycaemia or weight gain.', 1),
('f0000000-0000-0000-0000-000000000001', 'B', 'Sulfonylurea (e.g. gliclazide)', false, 'Ruled out because sulfonylureas are typically second-line, used when metformin is contraindicated or insufficient, and carry a higher risk of hypoglycaemia and weight gain than metformin.', 2),
('f0000000-0000-0000-0000-000000000001', 'C', 'Insulin', false, 'Ruled out because insulin is not first-line for newly diagnosed, asymptomatic type 2 diabetes; oral agents are tried first unless there is marked hyperglycaemia with symptoms or metabolic decompensation.', 3),
('f0000000-0000-0000-0000-000000000001', 'D', 'SGLT2 inhibitor alone', false, 'Ruled out because although SGLT2 inhibitors have a growing role, metformin remains the standard first-line agent for most patients with type 2 diabetes in the absence of established cardiovascular or renal disease driving an alternative choice.', 4),
('f0000000-0000-0000-0000-000000000001', 'E', 'Lifestyle advice alone with no medication', false, 'Ruled out because with an HbA1c of 58 mmol/mol (above the 48 mmol/mol diagnostic threshold and above target), pharmacological therapy alongside lifestyle changes is indicated, not lifestyle measures alone.', 5),
('f0000000-0000-0000-0000-000000000002', 'A', 'Continue metformin at the same dose', false, 'Ruled out because continuing metformin unchanged at this eGFR significantly increases the risk of life-threatening lactic acidosis.', 1),
('f0000000-0000-0000-0000-000000000002', 'B', 'Halve the dose and continue', false, 'Ruled out because although dose reduction is appropriate at an eGFR of 30-45, below 30 mL/min/1.73m2 metformin should be stopped entirely, not merely reduced.', 2),
('f0000000-0000-0000-0000-000000000002', 'C', 'Switch to a higher dose to improve control', false, 'Ruled out because increasing the dose in significant renal impairment further raises the risk of lactic acidosis rather than improving safety.', 3),
('f0000000-0000-0000-0000-000000000002', 'D', 'Stop metformin', true, 'Correct. Metformin is contraindicated at an eGFR below 30 mL/min/1.73m2 due to the risk of lactic acidosis from reduced renal clearance, so it should be stopped and an alternative agent considered.', 4),
('f0000000-0000-0000-0000-000000000002', 'E', 'Add a second oral agent without changing metformin', false, 'Ruled out because the priority at this eGFR is addressing the unsafe metformin dose itself, not simply adding further therapy on top of it.', 5),
('f0000000-0000-0000-0000-000000000003', 'A', 'Sulfonylurea', false, 'Ruled out because sulfonylureas have not demonstrated the same cardiovascular protective benefit and carry a higher hypoglycaemia risk, making them a less favourable choice in a patient with established ischaemic heart disease.', 1),
('f0000000-0000-0000-0000-000000000003', 'B', 'Thiazolidinedione (e.g. pioglitazone)', false, 'Ruled out because pioglitazone is associated with fluid retention and can worsen heart failure, making it a poor choice in a patient with cardiovascular disease.', 2),
('f0000000-0000-0000-0000-000000000003', 'C', 'SGLT2 inhibitor', true, 'Correct. SGLT2 inhibitors (e.g. empagliflozin) have strong trial evidence for reducing major adverse cardiovascular events and heart failure hospitalisation in patients with type 2 diabetes and established cardiovascular disease, making them a preferred second-line agent in this context.', 3),
('f0000000-0000-0000-0000-000000000003', 'D', 'DPP-4 inhibitor', false, 'Ruled out because DPP-4 inhibitors are generally cardiovascular-neutral rather than protective, and do not offer the same evidence of benefit as SGLT2 inhibitors in this population.', 4),
('f0000000-0000-0000-0000-000000000003', 'E', 'Insulin', false, 'Ruled out because insulin is not first choice as a second-line add-on in this context and does not carry the specific cardiovascular protective evidence of SGLT2 inhibitors.', 5),
('f0000000-0000-0000-0000-000000000004', 'A', 'Inhibition of renal glucose reabsorption in the proximal tubule', false, 'Ruled out because this describes the mechanism of SGLT2 inhibitors, not GLP-1 receptor agonists.', 1),
('f0000000-0000-0000-0000-000000000004', 'B', 'Glucose-dependent stimulation of insulin secretion and suppression of glucagon, with delayed gastric emptying', true, 'Correct. GLP-1 receptor agonists mimic the incretin hormone GLP-1, glucose-dependently enhancing insulin secretion, suppressing glucagon release, and slowing gastric emptying, which together lower blood glucose and promote satiety/weight loss with a low intrinsic hypoglycaemia risk.', 2),
('f0000000-0000-0000-0000-000000000004', 'C', 'Direct stimulation of peripheral glucose uptake via activation of AMP-activated protein kinase', false, 'Ruled out because this describes a proposed mechanism of metformin, not GLP-1 receptor agonists.', 3),
('f0000000-0000-0000-0000-000000000004', 'D', 'Closure of pancreatic beta-cell ATP-sensitive potassium channels independent of glucose level', false, 'Ruled out because this describes the glucose-independent mechanism of sulfonylureas, which is why they carry a higher hypoglycaemia risk than GLP-1 receptor agonists.', 4),
('f0000000-0000-0000-0000-000000000004', 'E', 'Inhibition of alpha-glucosidase enzymes in the small intestine', false, 'Ruled out because this describes the mechanism of acarbose, not GLP-1 receptor agonists.', 5),
('f0000000-0000-0000-0000-000000000005', 'A', 'Oral glucose tolerance test', false, 'Ruled out because the diagnosis of diabetes is already clear from the markedly elevated random glucose with symptoms; an OGTT is not needed to confirm diabetes here, and does not help distinguish type 1 from type 2.', 1),
('f0000000-0000-0000-0000-000000000005', 'B', 'HbA1c alone, with no further testing', false, $x$Ruled out because HbA1c confirms glycaemic control but does not distinguish between type 1 and type 2 diabetes, which matters for this patient's management (insulin requirement, screening for other autoimmune disease).$x$, 2),
('f0000000-0000-0000-0000-000000000005', 'C', 'Fasting lipid profile', false, 'Ruled out because although relevant to overall diabetes management, this does not help establish the underlying type of diabetes, which is the key diagnostic question raised by this atypical (lean, rapid-onset) presentation.', 3),
('f0000000-0000-0000-0000-000000000005', 'D', 'Abdominal ultrasound of the pancreas', false, 'Ruled out because imaging is not useful for distinguishing autoimmune type 1 diabetes from other causes; antibody and C-peptide testing are the appropriate next investigations.', 4),
('f0000000-0000-0000-0000-000000000005', 'E', 'Islet autoantibody testing (e.g. anti-GAD, anti-IA2)', true, 'Correct. A lean patient with rapid-onset osmotic symptoms, marked hyperglycaemia and a personal/family predisposition to autoimmune disease raises suspicion of type 1 diabetes; islet autoantibody testing supports this diagnosis by identifying the autoimmune beta-cell destruction underlying it.', 5),
('f0000000-0000-0000-0000-000000000006', 'A', 'Calcium channel blocker', false, 'Ruled out because calcium channel blockers do not have the specific renoprotective, antiproteinuric effect of ACE inhibitors/ARBs in diabetic nephropathy and are not first-line for this indication.', 1),
('f0000000-0000-0000-0000-000000000006', 'B', 'ACE inhibitor or angiotensin receptor blocker', true, 'Correct. In diabetic patients with confirmed microalbuminuria, an ACE inhibitor (or ARB if not tolerated) is first-line therapy, as these agents reduce intraglomerular pressure and slow progression of diabetic nephropathy, independent of blood pressure level.', 2),
('f0000000-0000-0000-0000-000000000006', 'C', 'Loop diuretic', false, 'Ruled out because loop diuretics treat fluid overload, not the underlying glomerular process causing microalbuminuria, and have no specific renoprotective role here.', 3),
('f0000000-0000-0000-0000-000000000006', 'D', 'High-dose aspirin', false, 'Ruled out because aspirin has no role in reducing progression of diabetic nephropathy or albuminuria.', 4),
('f0000000-0000-0000-0000-000000000006', 'E', 'Referral for renal biopsy', false, 'Ruled out because a renal biopsy is not routinely required to confirm diabetic nephropathy in a patient with a typical clinical picture (longstanding diabetes, microalbuminuria, preserved eGFR); treatment can be started on clinical grounds.', 5),
('f0000000-0000-0000-0000-000000000007', 'A', 'Increase the sulfonylurea dose to improve control', false, 'Ruled out because increasing the dose would worsen, not improve, the hypoglycaemia this patient is already experiencing.', 1),
('f0000000-0000-0000-0000-000000000007', 'B', 'Add a further oral hypoglycaemic agent without changing the sulfonylurea', false, 'Ruled out because adding further glucose-lowering therapy on top of a dose that is already causing hypoglycaemia would increase, not reduce, the risk of further episodes.', 2),
('f0000000-0000-0000-0000-000000000007', 'C', 'Start insulin therapy', false, 'Ruled out because starting insulin in a patient already experiencing hypoglycaemia on an oral agent would further increase hypoglycaemia risk rather than addressing the underlying cause.', 3),
('f0000000-0000-0000-0000-000000000007', 'D', 'No change is needed; reassure the patient', false, 'Ruled out because recurrent symptomatic hypoglycaemia, especially in an older adult, carries real risks (falls, cognitive impairment, cardiovascular events) and requires active management, not reassurance alone.', 4),
('f0000000-0000-0000-0000-000000000007', 'E', 'Reduce or stop the sulfonylurea and review overall glycaemic targets', true, 'Correct. Recurrent, symptomatic, biochemically confirmed hypoglycaemia in a patient on a sulfonylurea indicates the dose is too high (or the drug inappropriate) relative to his needs; the sulfonylurea should be reduced or stopped and glycaemic targets reviewed, particularly given his age.', 5),
('f0000000-0000-0000-0000-000000000008', 'A', 'Annual brain MRI', false, 'Ruled out because routine brain MRI is not part of standard diabetic surveillance; neurological complications are assessed clinically (e.g. peripheral neuropathy screening), not by routine imaging.', 1),
('f0000000-0000-0000-0000-000000000008', 'B', 'Annual colonoscopy', false, 'Ruled out because colonoscopy is not part of standard diabetic complication screening; it belongs to separate age-based bowel cancer screening programmes, not diabetes-specific surveillance.', 2),
('f0000000-0000-0000-0000-000000000008', 'C', 'Digital retinal photography screening', true, 'Correct. Annual diabetic retinal screening with digital photography is a standard component of diabetic review, aiming to detect diabetic retinopathy at an early, treatable stage before symptomatic visual loss occurs.', 3),
('f0000000-0000-0000-0000-000000000008', 'D', 'Annual chest X-ray', false, 'Ruled out because chest X-ray has no established role in routine diabetic complication screening.', 4),
('f0000000-0000-0000-0000-000000000008', 'E', 'Annual bone marrow biopsy', false, 'Ruled out because bone marrow biopsy has no role in diabetes surveillance; it is not part of standard diabetic complication screening.', 5),
('f0000000-0000-0000-0000-000000000009', 'A', 'IV fluid resuscitation followed by a fixed-rate intravenous insulin infusion', true, 'Correct. This is diabetic ketoacidosis (hyperglycaemia, ketosis, acidosis); management priorities are IV fluid resuscitation to correct dehydration and a fixed-rate intravenous insulin infusion to suppress ketogenesis and lower glucose, alongside potassium monitoring and replacement.', 1),
('f0000000-0000-0000-0000-000000000009', 'B', 'Subcutaneous rapid-acting insulin only', false, 'Ruled out because subcutaneous insulin has unreliable absorption in a dehydrated, acidotic patient; IV insulin via a fixed-rate infusion is required in DKA.', 2),
('f0000000-0000-0000-0000-000000000009', 'C', 'Oral rehydration alone, with insulin withheld', false, 'Ruled out because oral rehydration is inadequate for a patient with significant dehydration and acidosis, and withholding insulin would allow ongoing ketogenesis and worsening acidosis.', 3),
('f0000000-0000-0000-0000-000000000009', 'D', 'IV sodium bicarbonate as first-line treatment', false, 'Ruled out because bicarbonate is not routinely given in DKA even with a low pH; fluids and insulin correct the acidosis by resolving the underlying ketogenesis.', 4),
('f0000000-0000-0000-0000-000000000009', 'E', 'Long-acting insulin only, with short-acting insulin stopped', false, 'Ruled out because background long-acting insulin should generally be continued but does not itself deliver the rapid, high insulin exposure needed to switch off ketogenesis; a fixed-rate IV insulin infusion is required.', 5),
('f0000000-0000-0000-0000-000000000010', 'A', 'Diabetic ketoacidosis', false, 'Ruled out because DKA requires significant ketosis and acidosis, neither of which is present here (low ketones, near-normal pH), making HHS the more likely diagnosis in this context.', 1),
('f0000000-0000-0000-0000-000000000010', 'B', 'Hypoglycaemic coma', false, 'Ruled out because the glucose is markedly elevated (42 mmol/L), the opposite of the low glucose seen in hypoglycaemic coma.', 2),
('f0000000-0000-0000-0000-000000000010', 'C', 'Lactic acidosis (e.g. from metformin accumulation)', false, 'Ruled out because the blood gas shows a near-normal pH, inconsistent with a significant lactic acidosis, and the clinical picture is dominated by extreme hyperglycaemia and hyperosmolality.', 3),
('f0000000-0000-0000-0000-000000000010', 'D', 'Hyperosmolar hyperglycaemic state', true, 'Correct. Marked hyperglycaemia, high serum osmolality, absence of significant ketosis or acidosis, and altered consciousness in an older patient with type 2 diabetes is characteristic of hyperosmolar hyperglycaemic state (HHS), which differs from DKA in typically occurring without significant ketoacidosis.', 4),
('f0000000-0000-0000-0000-000000000010', 'E', 'Alcoholic ketoacidosis', false, 'Ruled out because alcoholic ketoacidosis typically presents with significant ketosis (often with normal or low glucose), not the marked hyperglycaemia with low ketones seen here.', 5),
('f0000000-0000-0000-0000-000000000011', 'A', 'Add potassium chloride to the IV fluids and continue the insulin infusion with close monitoring', true, 'Correct. Insulin drives potassium intracellularly, so hypokalaemia is an expected and potentially dangerous complication of DKA treatment; potassium should be added to the replacement fluids (with cardiac monitoring given ECG changes) while continuing insulin, which remains essential to resolve the ketoacidosis.', 1),
('f0000000-0000-0000-0000-000000000011', 'B', 'Stop the insulin infusion immediately', false, 'Ruled out because stopping insulin would halt resolution of the ketoacidosis, which remains the primary problem; the hypokalaemia is managed by adding potassium replacement, not by stopping insulin.', 2),
('f0000000-0000-0000-0000-000000000011', 'C', 'Give IV calcium gluconate', false, 'Ruled out because calcium gluconate is used to protect the myocardium in hyperkalaemia, not to treat hypokalaemia, which is the abnormality here.', 3),
('f0000000-0000-0000-0000-000000000011', 'D', 'Increase the insulin infusion rate', false, 'Ruled out because increasing insulin would further drive potassium intracellularly, worsening the hypokalaemia rather than correcting it.', 4),
('f0000000-0000-0000-0000-000000000011', 'E', 'Give IV fluids without any potassium replacement', false, 'Ruled out because failing to replace potassium in this context risks worsening hypokalaemia, with significant risk of cardiac arrhythmia.', 5),
('f0000000-0000-0000-0000-000000000012', 'A', 'IM glucagon', false, 'Ruled out because IM glucagon is reserved for patients who are unconscious or unable to safely swallow; this patient is conscious and able to take oral treatment.', 1),
('f0000000-0000-0000-0000-000000000012', 'B', 'IV 20% glucose', false, 'Ruled out because IV glucose is used when IV access is already available and oral treatment is not possible or has failed, not as first-line in a conscious patient who can swallow safely.', 2),
('f0000000-0000-0000-0000-000000000012', 'C', 'Give 15-20g of fast-acting oral carbohydrate', true, 'Correct. In a conscious patient able to swallow safely with symptomatic hypoglycaemia, 15-20g of fast-acting oral carbohydrate (e.g. glucose tablets or juice) is first-line treatment, with capillary glucose rechecked after 15 minutes and the dose repeated if still low.', 3),
('f0000000-0000-0000-0000-000000000012', 'D', 'Withhold treatment and recheck glucose in one hour', false, 'Ruled out because symptomatic hypoglycaemia with a glucose of 3.1 mmol/L requires prompt treatment, not a delayed recheck, given the risk of progression to more severe hypoglycaemia.', 4),
('f0000000-0000-0000-0000-000000000012', 'E', 'Increase her basal insulin pump rate', false, 'Ruled out because increasing insulin delivery would worsen, not correct, the current hypoglycaemia.', 5),
('f0000000-0000-0000-0000-000000000013', 'A', 'Typical diabetic ketoacidosis', false, $x$Ruled out because typical DKA is defined by marked hyperglycaemia (usually >11 mmol/L, often much higher) alongside ketosis and acidosis; this patient's glucose is only mildly elevated, which is the atypical feature pointing to the euglycaemic variant.$x$, 1),
('f0000000-0000-0000-0000-000000000013', 'B', 'Hyperosmolar hyperglycaemic state', false, $x$Ruled out because HHS is characterised by very high glucose with minimal ketosis, the opposite pattern to this patient's significant ketoacidosis with only mildly raised glucose.$x$, 2),
('f0000000-0000-0000-0000-000000000013', 'C', 'Gastroenteritis alone', false, 'Ruled out because although nausea and vomiting could suggest gastroenteritis, the significant ketosis and acidosis indicate an underlying metabolic emergency (euglycaemic DKA) rather than a simple infective cause.', 3),
('f0000000-0000-0000-0000-000000000013', 'D', 'Euglycaemic diabetic ketoacidosis', true, 'Correct. Significant ketosis and acidosis with a glucose level that is only mildly elevated (rather than markedly high) is characteristic of euglycaemic DKA, a recognised complication of SGLT2 inhibitor use, particularly in type 1 diabetes, where glucosuria masks the degree of insulin deficiency.', 4),
('f0000000-0000-0000-0000-000000000013', 'E', 'Lactic acidosis unrelated to diabetes', false, 'Ruled out because the markedly raised blood ketones point specifically to a ketotic process, and the SGLT2 inhibitor use is a well-recognised precipitant of euglycaemic DKA in this context.', 5),
('f0000000-0000-0000-0000-000000000014', 'A', 'Attempt to give oral glucose gel by mouth', false, 'Ruled out because giving anything orally to an unconscious patient carries a significant risk of aspiration; oral treatment is only appropriate in a conscious patient able to safely swallow.', 1),
('f0000000-0000-0000-0000-000000000014', 'B', 'Administer intramuscular glucagon if available and trained to do so', true, 'Correct. In severe hypoglycaemia with reduced consciousness and no IV access available, intramuscular glucagon is the appropriate emergency treatment for a trained family member or carer to give, as it stimulates hepatic glycogenolysis to raise blood glucose.', 2),
('f0000000-0000-0000-0000-000000000014', 'C', 'Wait for paramedics without giving any treatment', false, 'Ruled out because severe hypoglycaemia is a medical emergency where delay in treatment risks seizures, permanent neurological injury, or death; if glucagon is available, it should be given without waiting.', 3),
('f0000000-0000-0000-0000-000000000014', 'D', 'Give insulin to help stabilise blood sugar', false, 'Ruled out because giving insulin in hypoglycaemia would dangerously worsen the low blood glucose.', 4),
('f0000000-0000-0000-0000-000000000014', 'E', 'Place the patient in a warm bath to aid recovery', false, 'Ruled out because this does not address the underlying hypoglycaemia and delays appropriate emergency treatment.', 5),
('f0000000-0000-0000-0000-000000000015', 'A', 'Stop the intravenous insulin infusion immediately without restarting subcutaneous insulin', false, 'Ruled out because abruptly stopping IV insulin without overlapping subcutaneous cover risks a rapid return of insulin deficiency and rebound ketoacidosis.', 1),
('f0000000-0000-0000-0000-000000000015', 'B', 'Continue the intravenous insulin infusion indefinitely with no plan to transition', false, 'Ruled out because once DKA has resolved and the patient can eat normally, prolonged unnecessary IV insulin is not appropriate; transition to his usual subcutaneous regimen should occur.', 2),
('f0000000-0000-0000-0000-000000000015', 'C', 'Stop all insulin until his next meal', false, 'Ruled out because a patient with type 1 diabetes always requires background insulin, even without eating, to prevent recurrence of ketosis from absolute insulin deficiency.', 3),
('f0000000-0000-0000-0000-000000000015', 'D', 'Double his usual subcutaneous insulin doses for the next 24 hours', false, 'Ruled out because there is no indication to double his usual doses; his regular regimen should simply be restarted with appropriate overlap, not empirically increased.', 4),
('f0000000-0000-0000-0000-000000000015', 'E', 'Restart his regular subcutaneous insulin regimen and stop the intravenous infusion once it has been running alongside for at least 30-60 minutes', true, 'Correct. Once DKA has resolved (ketones <0.6 mmol/L, pH normalised) and the patient is eating and drinking, subcutaneous insulin should be restarted, with the IV infusion continued in overlap for at least 30-60 minutes after the first subcutaneous dose to prevent a rebound gap in insulin coverage and recurrence of ketosis.', 5),
('f0000000-0000-0000-0000-000000000016', 'A', 'Toxic multinodular goitre', false, $x$Ruled out because toxic multinodular goitre typically causes a nodular (not diffusely smooth) thyroid and does not cause thyroid eye disease, which is specific to Graves' disease.$x$, 1),
('f0000000-0000-0000-0000-000000000016', 'B', $x$Subacute (De Quervain's) thyroiditis$x$, false, 'Ruled out because subacute thyroiditis typically presents with a painful, tender thyroid and often a preceding viral illness, not the painless diffuse goitre with eye disease described here.', 2),
('f0000000-0000-0000-0000-000000000016', 'C', 'Toxic adenoma', false, 'Ruled out because a toxic adenoma causes a single palpable nodule with focal uptake on scintigraphy, not a diffusely enlarged gland, and does not cause thyroid eye disease.', 3),
('f0000000-0000-0000-0000-000000000016', 'D', $x$Graves' disease$x$, true, $x$Correct. Diffuse goitre, suppressed TSH with raised free T4, and thyroid eye disease (proptosis) together are characteristic of Graves' disease, an autoimmune condition caused by TSH receptor-stimulating antibodies.$x$, 4),
('f0000000-0000-0000-0000-000000000016', 'E', $x$Hashimoto's thyroiditis$x$, false, $x$Ruled out because Hashimoto's thyroiditis typically causes hypothyroidism (raised TSH, low T4), the opposite biochemical picture to that described here.$x$, 5),
('f0000000-0000-0000-0000-000000000017', 'A', 'Admit for supportive care, high-dose antithyroid drugs, beta-blockade, and treatment of the precipitant', true, 'Correct. Fever, marked tachycardia, agitation and confusion in a patient with poorly controlled hyperthyroidism and an infective precipitant is thyroid storm, a life-threatening emergency requiring admission, supportive care, high-dose antithyroid medication (e.g. propylthiouracil), beta-blockade to control adrenergic symptoms, and treatment of the underlying trigger.', 1),
('f0000000-0000-0000-0000-000000000017', 'B', 'Discharge home with an increased dose of carbimazole', false, 'Ruled out because thyroid storm is a life-threatening emergency requiring hospital admission and intensive multimodal treatment, not outpatient dose adjustment alone.', 2),
('f0000000-0000-0000-0000-000000000017', 'C', 'Withhold all thyroid medication until she is afebrile', false, 'Ruled out because withholding antithyroid treatment would allow ongoing excessive thyroid hormone effect, worsening the crisis; high-dose antithyroid drugs are part of the emergency management.', 3),
('f0000000-0000-0000-0000-000000000017', 'D', 'Radioiodine therapy as immediate treatment', false, $x$Ruled out because radioiodine is a longer-term definitive treatment for Graves' disease and is not appropriate as acute management of a life-threatening thyroid storm; it can, in fact, transiently worsen thyroid hormone release.$x$, 4),
('f0000000-0000-0000-0000-000000000017', 'E', 'IV insulin infusion', false, 'Ruled out because insulin has no role in the management of thyroid storm, which is not a diabetic emergency.', 5),
('f0000000-0000-0000-0000-000000000018', 'A', $x$Graves' disease$x$, false, $x$Ruled out because Graves' disease causes hyperthyroidism (suppressed TSH, raised T4), the opposite biochemical pattern to that described here.$x$, 1),
('f0000000-0000-0000-0000-000000000018', 'B', 'Subacute thyroiditis', false, $x$Ruled out because subacute thyroiditis typically presents with a painful thyroid and a transient hyperthyroid phase before hypothyroidism, and is not associated with strongly positive anti-TPO antibodies in the way Hashimoto's is.$x$, 2),
('f0000000-0000-0000-0000-000000000018', 'C', 'Sick euthyroid syndrome', false, 'Ruled out because sick euthyroid syndrome occurs in the context of acute severe illness with a characteristic pattern of low T3 and variable TSH/T4, not the clear primary hypothyroid picture with positive autoantibodies described here.', 3),
('f0000000-0000-0000-0000-000000000018', 'D', 'Iodine deficiency', false, 'Ruled out because iodine deficiency, while a cause of hypothyroidism worldwide, would not be associated with strongly positive anti-TPO antibodies, which specifically indicate an autoimmune process.', 4),
('f0000000-0000-0000-0000-000000000018', 'E', $x$Hashimoto's thyroiditis$x$, true, $x$Correct. Gradual-onset hypothyroid symptoms with a raised TSH, low free T4, and strongly positive anti-TPO antibodies is characteristic of Hashimoto's (autoimmune) thyroiditis, the most common cause of hypothyroidism in iodine-sufficient areas.$x$, 5),
('f0000000-0000-0000-0000-000000000019', 'A', 'Radioiodine uptake scan', false, 'Ruled out because radioiodine scanning is used to characterise nodules in the context of hyperthyroidism (functioning vs non-functioning), not as the primary investigation for a nodule with a normal TSH and suspicious ultrasound features, where cytology is needed.', 1),
('f0000000-0000-0000-0000-000000000019', 'B', 'Reassurance with no further investigation', false, 'Ruled out because the ultrasound features described (irregular margins, microcalcifications) are suspicious for malignancy and warrant tissue sampling, not reassurance alone.', 2),
('f0000000-0000-0000-0000-000000000019', 'C', 'Fine needle aspiration cytology', true, 'Correct. A thyroid nodule with sonographic features suspicious for malignancy (hypoechoic, irregular margins, microcalcifications) should undergo fine needle aspiration cytology to determine whether malignant cells are present and guide further management.', 3),
('f0000000-0000-0000-0000-000000000019', 'D', 'Immediate total thyroidectomy without prior biopsy', false, 'Ruled out because surgery is not undertaken without first establishing a tissue diagnosis via fine needle aspiration, except in specific circumstances; biopsy guides whether and what type of surgery is needed.', 4),
('f0000000-0000-0000-0000-000000000019', 'E', 'Repeat ultrasound in 12 months with no other action', false, 'Ruled out because suspicious sonographic features warrant prompt tissue sampling rather than a delayed repeat scan, given the possibility of malignancy.', 5),
('f0000000-0000-0000-0000-000000000020', 'A', $x$Graves' disease$x$, false, $x$Ruled out because Graves' disease would show high, not low, radioiodine uptake, reflecting active hormone synthesis rather than the passive release of preformed hormone seen in destructive thyroiditis.$x$, 1),
('f0000000-0000-0000-0000-000000000020', 'B', 'Postpartum thyroiditis (thyrotoxic phase)', true, $x$Correct. A destructive thyroiditis occurring within the first year postpartum, presenting with a transient thyrotoxic phase (low radioiodine uptake distinguishing it from Graves' disease, where uptake would be high) is characteristic of postpartum thyroiditis.$x$, 2),
('f0000000-0000-0000-0000-000000000020', 'C', 'Toxic multinodular goitre', false, 'Ruled out because this typically occurs in older patients with a nodular gland and would show increased (not low) radioiodine uptake in the hyperfunctioning nodules.', 3),
('f0000000-0000-0000-0000-000000000020', 'D', 'Subclinical hypothyroidism', false, 'Ruled out because this patient has a suppressed TSH with raised T4 (a hyperthyroid, not hypothyroid, biochemical picture).', 4),
('f0000000-0000-0000-0000-000000000020', 'E', 'Normal postpartum physiology', false, 'Ruled out because suppressed TSH with raised free T4 and low uptake represents a genuine thyroiditis process, not simply normal postpartum change.', 5),
('f0000000-0000-0000-0000-000000000021', 'A', 'Alendronic acid alone (if taken correctly, well separated from levothyroxine)', false, 'Ruled out because alendronic acid, taken correctly (fasting, well separated from other medications) does not typically interfere with levothyroxine absorption to the same degree as calcium or iron supplements, though timing errors could theoretically contribute.', 1),
('f0000000-0000-0000-0000-000000000021', 'B', 'Paracetamol', false, 'Ruled out because paracetamol has no recognised significant interaction with levothyroxine absorption or metabolism.', 2),
('f0000000-0000-0000-0000-000000000021', 'C', 'Vitamin D alone (without calcium)', false, 'Ruled out because vitamin D alone (without accompanying calcium) does not significantly impair levothyroxine absorption.', 3),
('f0000000-0000-0000-0000-000000000021', 'D', 'Calcium carbonate', true, 'Correct. Calcium carbonate (and iron supplements) can bind levothyroxine in the gut and reduce its absorption if taken at a similar time, leading to reduced effective dosing and a rise in TSH; levothyroxine should be taken well separated in time from calcium or iron preparations.', 4),
('f0000000-0000-0000-0000-000000000021', 'E', 'Simple analgesics such as codeine', false, 'Ruled out because codeine has no established interaction with levothyroxine absorption.', 5),
('f0000000-0000-0000-0000-000000000022', 'A', 'Papillary thyroid carcinoma', false, 'Ruled out because papillary thyroid carcinoma typically has an indolent course with slow growth, not the rapid, aggressive local invasion described here.', 1),
('f0000000-0000-0000-0000-000000000022', 'B', 'Follicular thyroid carcinoma', false, 'Ruled out because follicular carcinoma also tends to be slower growing, typically spreading haematogenously rather than presenting with this rapid, locally invasive picture.', 2),
('f0000000-0000-0000-0000-000000000022', 'C', 'Multinodular goitre', false, 'Ruled out because a benign multinodular goitre does not cause rapid growth with local invasion, hoarseness, or fixed lymphadenopathy.', 3),
('f0000000-0000-0000-0000-000000000022', 'D', 'Thyroid lymphoma', false, $x$Ruled out because although thyroid lymphoma can also grow rapidly, it is much rarer and typically arises in the context of pre-existing Hashimoto's thyroiditis; anaplastic carcinoma is the more classic answer for this rapidly invasive presentation in an older patient.$x$, 4),
('f0000000-0000-0000-0000-000000000022', 'E', 'Anaplastic thyroid carcinoma', true, 'Correct. A rapidly growing, hard, irregular thyroid mass with local invasion (hoarseness from recurrent laryngeal nerve involvement, dysphagia, fixed lymphadenopathy) in an older patient is characteristic of anaplastic thyroid carcinoma, an aggressive, rapidly progressive malignancy.', 5),
('f0000000-0000-0000-0000-000000000023', 'A', 'Acromegaly due to a growth hormone-secreting pituitary adenoma', true, 'Correct. Progressive acral and facial changes, headaches (from local mass effect), and failure of growth hormone to suppress with an oral glucose tolerance test (the diagnostic test for acromegaly) confirm excess growth hormone secretion, most commonly from a pituitary somatotroph adenoma.', 1),
('f0000000-0000-0000-0000-000000000023', 'B', 'Gigantism', false, 'Ruled out because gigantism describes excess growth hormone occurring before epiphyseal fusion in childhood, causing increased height; this adult patient has the post-fusion pattern of acromegaly (acral enlargement, not increased height).', 2),
('f0000000-0000-0000-0000-000000000023', 'C', $x$Cushing's syndrome$x$, false, $x$Ruled out because Cushing's syndrome causes centripetal obesity, striae and proximal myopathy from excess cortisol, not the acral/facial enlargement and failure of GH suppression described here.$x$, 3),
('f0000000-0000-0000-0000-000000000023', 'D', 'Hypothyroidism', false, 'Ruled out because hypothyroidism does not cause progressive acral enlargement or failure of growth hormone suppression on OGTT.', 4),
('f0000000-0000-0000-0000-000000000023', 'E', 'Simple obesity', false, 'Ruled out because obesity does not explain the specific pattern of acral/facial bony and soft tissue overgrowth or the biochemical failure of GH suppression.', 5),
('f0000000-0000-0000-0000-000000000024', 'A', 'Subarachnoid haemorrhage', false, 'Ruled out because although SAH also causes sudden severe headache, it would not typically produce this specific pattern of isolated third nerve palsy and hypotension linked to a known pituitary tumour; pituitary apoplexy is the more specific and likely diagnosis in this context.', 1),
('f0000000-0000-0000-0000-000000000024', 'B', 'Pituitary apoplexy', true, 'Correct. Sudden severe headache, visual disturbance, ophthalmoplegia (third nerve palsy from cavernous sinus compression) and haemodynamic compromise (from acute cortisol deficiency) in a patient with a known pituitary macroadenoma is characteristic of pituitary apoplexy, caused by haemorrhage or infarction within the tumour.', 2),
('f0000000-0000-0000-0000-000000000024', 'C', 'Simple migraine', false, 'Ruled out because migraine does not cause a third nerve palsy, visual acuity loss, or haemodynamic compromise, and would not be explained by the underlying pituitary tumour.', 3),
('f0000000-0000-0000-0000-000000000024', 'D', 'Bacterial meningitis', false, 'Ruled out because there is no fever or neck stiffness described, and the specific combination of ophthalmoplegia and hypotension in a patient with a known pituitary adenoma points to apoplexy rather than infection.', 4),
('f0000000-0000-0000-0000-000000000024', 'E', 'Cluster headache', false, 'Ruled out because cluster headache does not cause a third nerve palsy, marked visual loss, or hypotension, and is not linked to an underlying pituitary tumour.', 5),
('f0000000-0000-0000-0000-000000000025', 'A', 'Immediate transsphenoidal surgery', false, 'Ruled out because surgery is not first-line for a prolactinoma; dopamine agonists are highly effective medical therapy and are tried first, with surgery reserved for resistant cases or those intolerant of medical therapy.', 1),
('f0000000-0000-0000-0000-000000000025', 'B', 'External beam radiotherapy', false, 'Ruled out because radiotherapy is not first-line treatment for a prolactinoma; it is reserved for cases not controlled by medical therapy or surgery.', 2),
('f0000000-0000-0000-0000-000000000025', 'C', 'Dopamine agonist therapy (e.g. cabergoline)', true, 'Correct. A prolactinoma causing amenorrhoea and galactorrhoea with markedly elevated prolactin is first-line treated medically with a dopamine agonist (e.g. cabergoline or bromocriptine), which typically shrinks the tumour and normalises prolactin without the need for surgery.', 3),
('f0000000-0000-0000-0000-000000000025', 'D', 'Observation alone with no treatment', false, 'Ruled out because significant hyperprolactinaemia with symptomatic amenorrhoea and galactorrhoea, and a measurable pituitary lesion, warrants active treatment, not observation.', 4),
('f0000000-0000-0000-0000-000000000025', 'E', 'Oestrogen replacement therapy without addressing the prolactin', false, 'Ruled out because this would not address the underlying cause (the prolactinoma) and would not be appropriate without first correcting the hyperprolactinaemia driving the amenorrhoea.', 5),
('f0000000-0000-0000-0000-000000000026', 'A', 'Postpartum thyroiditis', false, 'Ruled out because postpartum thyroiditis causes an isolated thyroid dysfunction (typically transient thyrotoxicosis then hypothyroidism), not the combined failure of lactation and amenorrhoea reflecting multiple pituitary hormone deficiencies.', 1),
('f0000000-0000-0000-0000-000000000026', 'B', 'Prolactinoma', false, 'Ruled out because a prolactinoma would cause excess (not absent) prolactin, and would not explain the failure to lactate following a postpartum haemorrhage, which specifically points to pituitary infarction.', 2),
('f0000000-0000-0000-0000-000000000026', 'C', 'Normal postpartum recovery', false, 'Ruled out because failure to lactate combined with amenorrhoea and hypothyroid symptoms following a major obstetric haemorrhage is not normal and reflects a recognised complication requiring specific diagnosis and treatment.', 3),
('f0000000-0000-0000-0000-000000000026', 'D', 'Postpartum depression', false, 'Ruled out because although fatigue can occur in depression, the combination of failed lactation, amenorrhoea and cold intolerance following major postpartum haemorrhage points to an organic endocrine cause (hypopituitarism), not a primary mood disorder.', 4),
('f0000000-0000-0000-0000-000000000026', 'E', 'Sheehan syndrome', true, 'Correct. Failure to lactate and amenorrhoea following a significant postpartum haemorrhage, with subsequent features of hypopituitarism (fatigue, cold intolerance), is characteristic of Sheehan syndrome, caused by ischaemic pituitary necrosis following severe postpartum blood loss.', 5),
('f0000000-0000-0000-0000-000000000027', 'A', 'Diabetes insipidus', false, 'Ruled out because diabetes insipidus causes dilute urine and hypernatraemia (from ADH deficiency or resistance), the opposite pattern to the concentrated urine and hyponatraemia described here.', 1),
('f0000000-0000-0000-0000-000000000027', 'B', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH)', true, 'Correct. Euvolaemic hyponatraemia with inappropriately concentrated urine and low plasma osmolality, in a patient with small cell lung cancer (a classic cause of ectopic ADH secretion), is characteristic of SIADH.', 2),
('f0000000-0000-0000-0000-000000000027', 'C', 'Primary polydipsia', false, 'Ruled out because primary polydipsia typically causes dilute urine (appropriately suppressed ADH) as the kidneys try to excrete the excess free water, not the inappropriately concentrated urine seen in SIADH.', 3),
('f0000000-0000-0000-0000-000000000027', 'D', $x$Addison's disease$x$, false, $x$Ruled out because although Addison's disease can cause hyponatraemia, it is typically associated with hypovolaemia, hyperkalaemia and hypotension, not the euvolaemic picture described here.$x$, 4),
('f0000000-0000-0000-0000-000000000027', 'E', 'Diuretic-induced hyponatraemia', false, 'Ruled out because there is no history of diuretic use given, and the clinical and biochemical picture with a strong paraneoplastic association (small cell lung cancer) points specifically to SIADH.', 5),
('f0000000-0000-0000-0000-000000000028', 'A', 'Cranial diabetes insipidus', true, 'Correct. Polyuria with dilute urine and rising serum sodium following pituitary surgery reflects damage to ADH-producing/releasing structures (hypothalamus or posterior pituitary), causing cranial diabetes insipidus -- a well-recognised complication of transsphenoidal surgery.', 1),
('f0000000-0000-0000-0000-000000000028', 'B', 'SIADH', false, 'Ruled out because SIADH causes hyponatraemia with concentrated urine, the opposite pattern to the hypernatraemia with dilute urine seen here.', 2),
('f0000000-0000-0000-0000-000000000028', 'C', 'Diabetes mellitus', false, 'Ruled out because there is no mention of hyperglycaemia, and the described picture (polyuria with dilute urine and hypernatraemia) reflects a water balance disorder (diabetes insipidus), not glucose-driven osmotic diuresis.', 3),
('f0000000-0000-0000-0000-000000000028', 'D', 'Normal postoperative diuresis', false, 'Ruled out because the degree of polyuria, marked thirst, and rising serum sodium are outside the range of expected normal postoperative fluid shifts and reflect a specific ADH deficiency requiring treatment.', 4),
('f0000000-0000-0000-0000-000000000028', 'E', 'Adrenal insufficiency', false, 'Ruled out because adrenal insufficiency typically causes hyponatraemia and hypotension, not the hypernatraemia with dilute polyuria described here.', 5),
('f0000000-0000-0000-0000-000000000029', 'A', 'Compression of the optic nerve anterior to the chiasm on one side only', false, 'Ruled out because unilateral optic nerve compression would cause monocular visual loss, not the bilateral, symmetric bitemporal field defect described, which specifically localises to the chiasm.', 1),
('f0000000-0000-0000-0000-000000000029', 'B', 'Compression of the optic tract posterior to the chiasm', false, 'Ruled out because a post-chiasmal (optic tract) lesion causes a homonymous (not bitemporal) hemianopia, affecting the same side of the visual field in both eyes.', 2),
('f0000000-0000-0000-0000-000000000029', 'C', 'Compression of the decussating nasal retinal fibres at the optic chiasm', true, 'Correct. A pituitary macroadenoma expanding superiorly classically compresses the optic chiasm from below, affecting the crossing (decussating) nasal retinal fibres from each eye, which carry information from the temporal visual fields, producing bitemporal hemianopia.', 3),
('f0000000-0000-0000-0000-000000000029', 'D', 'Occipital cortex ischaemia', false, 'Ruled out because occipital cortex lesions cause homonymous hemianopia (often with macular sparing), not the bitemporal pattern seen with chiasmal compression, and would not be explained by a pituitary mass.', 4),
('f0000000-0000-0000-0000-000000000029', 'E', 'Direct compression of the optic radiations', false, 'Ruled out because optic radiation lesions cause homonymous quadrantanopias, not the bitemporal hemianopia pattern caused by chiasmal compression.', 5),
('f0000000-0000-0000-0000-000000000030', 'A', 'Secondary adrenal insufficiency (pituitary cause)', false, 'Ruled out because secondary adrenal insufficiency results from ACTH deficiency, which would not cause hyperpigmentation (since ACTH is low, not high) or the mineralocorticoid deficiency causing hyperkalaemia, as aldosterone secretion is largely ACTH-independent.', 1),
('f0000000-0000-0000-0000-000000000030', 'B', $x$Conn's syndrome (primary hyperaldosteronism)$x$, false, $x$Ruled out because Conn's syndrome causes hypertension with hypokalaemia from aldosterone excess, the opposite electrolyte pattern to that described here.$x$, 2),
('f0000000-0000-0000-0000-000000000030', 'C', $x$Cushing's syndrome$x$, false, $x$Ruled out because Cushing's syndrome results from cortisol excess, causing hypertension and often hypokalaemia, not the hypotension, hyperkalaemia and low cortisol seen in this patient.$x$, 3),
('f0000000-0000-0000-0000-000000000030', 'D', $x$Addison's disease (primary adrenal insufficiency)$x$, true, $x$Correct. Fatigue, postural hypotension, hyponatraemia with hyperkalaemia, and hyperpigmentation (from excess ACTH cross-reacting with melanocyte receptors due to loss of cortisol negative feedback) together are characteristic of primary adrenal insufficiency (Addison's disease).$x$, 4),
('f0000000-0000-0000-0000-000000000030', 'E', 'Simple dehydration', false, 'Ruled out because dehydration alone would not explain the hyperpigmentation or the specific hyponatraemia-with-hyperkalaemia pattern together with a low cortisol.', 5),
('f0000000-0000-0000-0000-000000000031', 'A', 'IV hydrocortisone and IV fluid resuscitation', true, 'Correct. This is an Addisonian (adrenal) crisis, precipitated by intercurrent illness in a patient with known adrenal insufficiency who is unable to mount an adequate cortisol response and cannot absorb oral medication due to vomiting; immediate IV hydrocortisone and IV fluid resuscitation are life-saving.', 1),
('f0000000-0000-0000-0000-000000000031', 'B', 'Double her oral hydrocortisone dose and monitor at home', false, 'Ruled out because with severe vomiting she cannot reliably absorb oral medication, and her haemodynamic instability (hypotension, drowsiness) indicates a life-threatening crisis requiring emergency IV treatment, not home management.', 2),
('f0000000-0000-0000-0000-000000000031', 'C', 'IV fluids alone, without steroid replacement', false, 'Ruled out because fluids alone do not address the underlying cortisol deficiency driving the crisis; IV hydrocortisone is essential alongside fluid resuscitation.', 3),
('f0000000-0000-0000-0000-000000000031', 'D', 'Withhold steroids until formal Synacthen testing confirms the diagnosis', false, $x$Ruled out because in a patient with known Addison's disease presenting in crisis, treatment must be given immediately on clinical grounds; delaying for confirmatory testing risks death.$x$, 4),
('f0000000-0000-0000-0000-000000000031', 'E', 'Oral fludrocortisone only', false, 'Ruled out because oral medication cannot be reliably absorbed during severe vomiting, and IV hydrocortisone (which also has mineralocorticoid activity at high doses) is the priority in an acute crisis rather than fludrocortisone alone.', 5),
('f0000000-0000-0000-0000-000000000032', 'A', $x$Primary adrenal insufficiency (Addison's disease)$x$, false, 'Ruled out because his adrenal glands are intrinsically normal but suppressed by exogenous steroids (a secondary, not primary, process); this distinction matters as the mechanism (and expected recovery with steroid weaning) differs from autoimmune primary adrenal failure.', 1),
('f0000000-0000-0000-0000-000000000032', 'B', 'Anaphylaxis to the surgical anaesthetic', false, 'Ruled out because there is no mention of an allergic trigger, and the clinical context (abrupt steroid withdrawal, blunted ACTH response) specifically points to adrenal insufficiency rather than an allergic reaction.', 2),
('f0000000-0000-0000-0000-000000000032', 'C', 'Simple postoperative hypovolaemia unrelated to steroids', false, 'Ruled out because the blunted ACTH stimulation test result specifically confirms an adrenal cause, not simple volume depletion, which would show a normal cortisol response.', 3),
('f0000000-0000-0000-0000-000000000032', 'D', 'Secondary adrenal insufficiency from hypothalamic-pituitary-adrenal axis suppression', true, 'Correct. Long-term exogenous glucocorticoid therapy suppresses the hypothalamic-pituitary-adrenal axis via negative feedback, causing adrenal atrophy; abrupt cessation, especially around the physiological stress of surgery, unmasks this secondary adrenal insufficiency, precipitating an adrenal crisis.', 4),
('f0000000-0000-0000-0000-000000000032', 'E', 'Septic shock', false, 'Ruled out because there is no mention of infective source or fever, and the history of abrupt steroid withdrawal with a blunted ACTH response points specifically to adrenal insufficiency.', 5),
('f0000000-0000-0000-0000-000000000033', 'A', 'High-dose dexamethasone suppression test as the very first step', false, 'Ruled out because the high-dose test is used after establishing whether the cause is ACTH-dependent, to help distinguish pituitary from ectopic ACTH sources; ACTH measurement comes first to establish dependency.', 1),
('f0000000-0000-0000-0000-000000000033', 'B', 'Adrenal CT as the first investigation, before ACTH measurement', false, 'Ruled out because imaging should be directed by the ACTH result (adrenal imaging if ACTH-independent, pituitary MRI if ACTH-dependent); ordering adrenal CT before establishing ACTH status risks unnecessary or misdirected imaging.', 2),
('f0000000-0000-0000-0000-000000000033', 'C', '24-hour urinary free cortisol collection as the definitive next step', false, $x$Ruled out because urinary free cortisol is one of several tests used to confirm the diagnosis of Cushing's syndrome (which has already been established here); it does not help distinguish the underlying cause, which is the current question.$x$, 3),
('f0000000-0000-0000-0000-000000000033', 'D', 'Insulin tolerance test', false, $x$Ruled out because the insulin tolerance test assesses the growth hormone and cortisol axes in suspected pituitary hormone deficiency, not to determine the source of cortisol excess in confirmed Cushing's syndrome.$x$, 4),
('f0000000-0000-0000-0000-000000000033', 'E', 'Plasma ACTH level', true, $x$Correct. Having confirmed endogenous Cushing's syndrome (elevated late-night cortisol, failure to suppress with low-dose dexamethasone) in a patient not taking exogenous steroids, measuring plasma ACTH is the key next step to distinguish ACTH-dependent (pituitary or ectopic) from ACTH-independent (adrenal) causes, guiding further imaging.$x$, 5),
('f0000000-0000-0000-0000-000000000034', 'A', 'Secondary hyperaldosteronism (e.g. renal artery stenosis)', false, 'Ruled out because secondary hyperaldosteronism is driven by high renin (e.g. from reduced renal perfusion), which in turn raises aldosterone; here renin is suppressed, not elevated, pointing to a primary adrenal cause.', 1),
('f0000000-0000-0000-0000-000000000034', 'B', $x$Primary hyperaldosteronism (Conn's syndrome)$x$, true, 'Correct. Resistant hypertension with hypokalaemia, raised aldosterone and suppressed renin (giving a high aldosterone:renin ratio) is characteristic of primary hyperaldosteronism, in which autonomous adrenal aldosterone secretion causes sodium/water retention (suppressing renin) and potassium wasting.', 2),
('f0000000-0000-0000-0000-000000000034', 'C', $x$Cushing's syndrome$x$, false, $x$Ruled out because although Cushing's syndrome can cause hypertension and hypokalaemia (at very high cortisol levels), the specific biochemical pattern of raised aldosterone with suppressed renin points to primary hyperaldosteronism, not cortisol excess.$x$, 3),
('f0000000-0000-0000-0000-000000000034', 'D', 'Phaeochromocytoma', false, 'Ruled out because phaeochromocytoma causes episodic hypertension with catecholamine excess (palpitations, sweating, headache), not this specific aldosterone/renin pattern.', 4),
('f0000000-0000-0000-0000-000000000034', 'E', 'Essential hypertension', false, 'Ruled out because essential hypertension would not explain the hypokalaemia or the markedly abnormal aldosterone:renin ratio, both of which point to a specific secondary (endocrine) cause.', 5),
('f0000000-0000-0000-0000-000000000035', 'A', 'Panic disorder', false, 'Ruled out because although panic attacks can cause palpitations and sweating, they do not typically cause such markedly elevated blood pressure or raised urinary metanephrines, which specifically confirm catecholamine excess.', 1),
('f0000000-0000-0000-0000-000000000035', 'B', 'Primary hyperaldosteronism', false, 'Ruled out because primary hyperaldosteronism causes sustained (not episodic) hypertension with hypokalaemia, not the paroxysmal catecholamine-driven attacks described here.', 2),
('f0000000-0000-0000-0000-000000000035', 'C', 'Phaeochromocytoma', true, 'Correct. Episodic severe headache, palpitations, sweating and pallor with markedly elevated blood pressure during attacks, confirmed by raised urinary metanephrines, is the classic triad and biochemical confirmation of phaeochromocytoma, a catecholamine-secreting adrenal medullary tumour.', 3),
('f0000000-0000-0000-0000-000000000035', 'D', 'Thyrotoxicosis', false, 'Ruled out because although thyrotoxicosis can cause palpitations and sweating, it does not typically cause discrete episodic severe hypertensive crises, and would not explain the markedly raised urinary metanephrines.', 4),
('f0000000-0000-0000-0000-000000000035', 'E', 'Essential hypertension with anxiety', false, 'Ruled out because the episodic, severe nature of the attacks with objectively confirmed catecholamine excess (raised metanephrines) points to a specific secondary cause, not simple essential hypertension with anxiety.', 5),
('f0000000-0000-0000-0000-000000000036', 'A', 'Congenital hypothyroidism', false, 'Ruled out because congenital hypothyroidism does not cause ambiguous genitalia, salt-wasting electrolyte disturbance, or elevated 17-hydroxyprogesterone.', 1),
('f0000000-0000-0000-0000-000000000036', 'B', 'Pyloric stenosis', false, 'Ruled out because pyloric stenosis typically causes hypochloraemic, hypokalaemic metabolic alkalosis from vomiting, not the hyperkalaemia and ambiguous genitalia described here.', 2),
('f0000000-0000-0000-0000-000000000036', 'C', 'Congenital adrenal hyperplasia (21-hydroxylase deficiency)', true, 'Correct. A salt-wasting adrenal crisis (hyponatraemia, hyperkalaemia) in a neonate with ambiguous genitalia and markedly elevated 17-hydroxyprogesterone is characteristic of classic congenital adrenal hyperplasia due to 21-hydroxylase deficiency, in which impaired cortisol and aldosterone synthesis leads to shunting of precursors towards androgen production.', 3),
('f0000000-0000-0000-0000-000000000036', 'D', 'Neonatal sepsis alone', false, 'Ruled out because although sepsis can cause a similarly unwell neonate, it does not explain the ambiguous genitalia or the specific, markedly elevated 17-hydroxyprogesterone, which is diagnostic of CAH.', 4),
('f0000000-0000-0000-0000-000000000036', 'E', $x$Addison's disease (autoimmune)$x$, false, $x$Ruled out because autoimmune Addison's disease does not present in the neonatal period with ambiguous genitalia; the combination described is specific to a congenital enzyme defect (21-hydroxylase deficiency).$x$, 5),
('f0000000-0000-0000-0000-000000000037', 'A', 'Malignancy-associated hypercalcaemia', false, 'Ruled out because hypercalcaemia of malignancy typically suppresses PTH (via negative feedback from the high calcium, often driven by PTHrP rather than PTH itself), the opposite of the raised PTH seen here.', 1),
('f0000000-0000-0000-0000-000000000037', 'B', 'Familial hypocalciuric hypercalcaemia', false, 'Ruled out because FHH classically causes low, not normal, 24-hour urinary calcium excretion relative to the degree of hypercalcaemia; normal urinary calcium here makes primary hyperparathyroidism more likely.', 2),
('f0000000-0000-0000-0000-000000000037', 'C', 'Vitamin D toxicity', false, 'Ruled out because vitamin D toxicity causes hypercalcaemia with a suppressed (not raised) PTH, due to appropriate negative feedback from the elevated calcium.', 3),
('f0000000-0000-0000-0000-000000000037', 'D', 'Secondary hyperparathyroidism', false, 'Ruled out because secondary hyperparathyroidism occurs in response to hypocalcaemia (e.g. from vitamin D deficiency or CKD), presenting with low or low-normal calcium and raised PTH, not the elevated calcium described here.', 4),
('f0000000-0000-0000-0000-000000000037', 'E', 'Primary hyperparathyroidism', true, 'Correct. Elevated calcium with an inappropriately raised (rather than suppressed) PTH is characteristic of primary hyperparathyroidism, most commonly from a solitary parathyroid adenoma autonomously secreting PTH.', 5),
('f0000000-0000-0000-0000-000000000038', 'A', 'Osteomalacia', true, 'Correct. Bone pain, proximal myopathy, low calcium and phosphate, raised alkaline phosphatase, and low vitamin D in a housebound patient with limited sun exposure (a major risk factor for vitamin D deficiency) is characteristic of osteomalacia, in which defective bone mineralisation occurs due to vitamin D deficiency.', 1),
('f0000000-0000-0000-0000-000000000038', 'B', 'Osteoporosis', false, 'Ruled out because osteoporosis is a disorder of reduced bone mass with normal mineralisation and typically normal calcium, phosphate and alkaline phosphatase, unlike the abnormal biochemistry described here.', 2),
('f0000000-0000-0000-0000-000000000038', 'C', $x$Paget's disease of bone$x$, false, $x$Ruled out because Paget's disease typically causes an isolated raised alkaline phosphatase with normal calcium and phosphate, not the combined hypocalcaemia and hypophosphataemia seen here.$x$, 3),
('f0000000-0000-0000-0000-000000000038', 'D', 'Multiple myeloma', false, 'Ruled out because myeloma typically causes hypercalcaemia (not hypocalcaemia) from osteoclastic bone resorption, along with other features (anaemia, renal impairment) not described here.', 4),
('f0000000-0000-0000-0000-000000000038', 'E', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis causes an inflammatory small-joint arthropathy, not the biochemical pattern of hypocalcaemia, hypophosphataemia and vitamin D deficiency described here.', 5),
('f0000000-0000-0000-0000-000000000039', 'A', 'Osteomalacia', false, 'Ruled out because osteomalacia causes low calcium and phosphate alongside the raised alkaline phosphatase, whereas this patient has normal calcium and phosphate with an isolated ALP rise.', 1),
('f0000000-0000-0000-0000-000000000039', 'B', $x$Paget's disease of bone$x$, true, $x$Correct. An isolated markedly raised alkaline phosphatase with normal calcium and phosphate, localised bone pain, bony deformity, increasing skull size, and a mixed lytic/sclerotic radiographic pattern is classic for Paget's disease of bone, a disorder of excessive, disorganised bone remodelling.$x$, 2),
('f0000000-0000-0000-0000-000000000039', 'C', 'Bone metastases', false, $x$Ruled out because although metastases can raise alkaline phosphatase, the specific radiographic pattern (thickened, deformed bone with mixed lytic/sclerotic change) and the localised, chronic nature of the presentation are more typical of Paget's disease than metastatic disease.$x$, 3),
('f0000000-0000-0000-0000-000000000039', 'D', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism causes hypercalcaemia, not the normal calcium seen here, and does not typically cause this specific pattern of localised bony deformity.', 4),
('f0000000-0000-0000-0000-000000000039', 'E', 'Osteoporosis', false, 'Ruled out because osteoporosis causes reduced bone density without the specific mixed lytic/sclerotic deformity or the marked alkaline phosphatase elevation described.', 5),
('f0000000-0000-0000-0000-000000000040', 'A', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism typically causes hypercalcaemia with raised PTH, the opposite calcium pattern to the hypocalcaemia seen here, which is driven by the underlying renal disease.', 1),
('f0000000-0000-0000-0000-000000000040', 'B', 'Tertiary hyperparathyroidism', false, $x$Ruled out because tertiary hyperparathyroidism refers to autonomous PTH secretion (with resulting hypercalcaemia) that develops after prolonged secondary hyperparathyroidism, typically in long-standing or dialysis-dependent CKD; this patient's calcium is still low, consistent with the secondary (compensatory) stage.$x$, 2),
('f0000000-0000-0000-0000-000000000040', 'C', 'Vitamin D toxicity', false, 'Ruled out because vitamin D toxicity causes hypercalcaemia with suppressed PTH, not the hypocalcaemia with raised PTH described here.', 3),
('f0000000-0000-0000-0000-000000000040', 'D', 'Secondary hyperparathyroidism due to chronic kidney disease', true, 'Correct. In advanced CKD, reduced renal phosphate excretion (causing hyperphosphataemia) and reduced renal activation of vitamin D both contribute to hypocalcaemia, which drives compensatory parathyroid hormone secretion, producing secondary hyperparathyroidism.', 4),
('f0000000-0000-0000-0000-000000000040', 'E', 'Familial hypocalciuric hypercalcaemia', false, 'Ruled out because FHH causes mild hypercalcaemia, not the hypocalcaemia seen in this patient, and is unrelated to chronic kidney disease.', 5),
('f0000000-0000-0000-0000-000000000041', 'A', 'Oral calcium supplementation', false, $x$Ruled out because giving additional calcium would dangerously worsen this patient's already severe hypercalcaemia.$x$, 1),
('f0000000-0000-0000-0000-000000000041', 'B', 'IV 0.9% saline rehydration followed by an IV bisphosphonate', true, 'Correct. Severe symptomatic hypercalcaemia of malignancy is treated first with aggressive IV isotonic saline rehydration (to correct volume depletion and promote renal calcium excretion), followed by an IV bisphosphonate (e.g. zoledronic acid) to inhibit osteoclastic bone resorption and provide more sustained calcium lowering.', 2),
('f0000000-0000-0000-0000-000000000041', 'C', 'Loop diuretic as first-line treatment before fluids', false, 'Ruled out because loop diuretics are not first-line and should only be considered cautiously after adequate rehydration, as giving them to a volume-depleted patient can worsen renal function and hypercalcaemia.', 3),
('f0000000-0000-0000-0000-000000000041', 'D', 'Oral bisphosphonate alone', false, 'Ruled out because oral bisphosphonates have poor bioavailability and are not appropriate for severe, symptomatic hypercalcaemia, which requires IV rehydration and IV bisphosphonate therapy.', 4),
('f0000000-0000-0000-0000-000000000041', 'E', 'Restrict fluids to avoid fluid overload', false, 'Ruled out because fluid restriction would worsen the hypercalcaemia; aggressive rehydration (not restriction) is the cornerstone of initial management, as patients are typically significantly volume-depleted from calcium-induced nephrogenic diabetes insipidus and vomiting.', 5),
('f0000000-0000-0000-0000-000000000042', 'A', 'Recurrent laryngeal nerve injury', false, $x$Ruled out because recurrent laryngeal nerve injury causes voice hoarseness or stridor from vocal cord paralysis, not the neuromuscular irritability (tetany, Chvostek's and Trousseau's signs) reflecting hypocalcaemia described here.$x$, 1),
('f0000000-0000-0000-0000-000000000042', 'B', 'Wound infection', false, 'Ruled out because wound infection would present with local signs of infection (redness, swelling, fever), not the specific signs of neuromuscular hyperexcitability from hypocalcaemia described here.', 2),
('f0000000-0000-0000-0000-000000000042', 'C', 'Thyroid storm', false, $x$Ruled out because thyroid storm causes fever, tachycardia and agitation from excess thyroid hormone, not tetany and positive Chvostek's/Trousseau's signs, which specifically reflect hypocalcaemia.$x$, 3),
('f0000000-0000-0000-0000-000000000042', 'D', 'Normal postoperative recovery', false, 'Ruled out because tetany and positive neuromuscular excitability signs are not normal and indicate significant hypocalcaemia requiring prompt recognition and calcium replacement.', 4),
('f0000000-0000-0000-0000-000000000042', 'E', 'Post-surgical hypoparathyroidism', true, $x$Correct. Perioral tingling, tetany, a positive Chvostek's sign (facial twitching on tapping the facial nerve) and a positive Trousseau's sign (carpal spasm with cuff inflation) following thyroid surgery indicate hypocalcaemia from inadvertent damage to or removal of the parathyroid glands during thyroidectomy.$x$, 5),
('f0000000-0000-0000-0000-000000000043', 'A', 'Osteoporosis', true, 'Correct. A T-score of -2.5 or below on DEXA scanning defines osteoporosis; combined with a low-trauma (fragility) fracture and normal calcium/phosphate/vitamin D biochemistry, this confirms primary osteoporosis (reduced bone mass with normal mineralisation) rather than a metabolic bone disease such as osteomalacia.', 1),
('f0000000-0000-0000-0000-000000000043', 'B', 'Osteomalacia', false, 'Ruled out because osteomalacia is characterised by abnormal biochemistry (low calcium/phosphate, raised alkaline phosphatase, low vitamin D), all of which are normal in this patient, distinguishing it from osteoporosis.', 2),
('f0000000-0000-0000-0000-000000000043', 'C', 'Osteopenia', false, $x$Ruled out because osteopenia is defined as a T-score between -1.0 and -2.5; this patient's T-score of -2.7 falls below that range, meeting criteria for osteoporosis rather than the milder osteopenia.$x$, 3),
('f0000000-0000-0000-0000-000000000043', 'D', $x$Paget's disease of bone$x$, false, $x$Ruled out because Paget's disease causes a localised, markedly raised alkaline phosphatase with a specific radiographic pattern, not a low DEXA T-score with normal biochemistry.$x$, 4),
('f0000000-0000-0000-0000-000000000043', 'E', 'Normal bone density for age', false, 'Ruled out because a T-score of -2.7 is well below the threshold for normal bone density and meets diagnostic criteria for osteoporosis, particularly in the context of a fragility fracture.', 5),
('f0000000-0000-0000-0000-000000000044', 'A', 'Polygenic hypercholesterolaemia', false, 'Ruled out because polygenic hypercholesterolaemia typically causes more modest LDL elevation without tendon xanthomata or such a strong pattern of premature family cardiovascular death.', 1),
('f0000000-0000-0000-0000-000000000044', 'B', 'Metabolic syndrome', false, 'Ruled out because metabolic syndrome is characterised by a cluster of central obesity, hypertension, dyslipidaemia (typically raised triglycerides and low HDL rather than markedly raised LDL) and insulin resistance, not this specific pattern of xanthomata and severely elevated LDL.', 2),
('f0000000-0000-0000-0000-000000000044', 'C', 'Familial hypercholesterolaemia', true, 'Correct. Markedly elevated LDL cholesterol, tendon xanthomata, and a family history of premature cardiovascular death together are characteristic of familial hypercholesterolaemia, an autosomal dominant disorder typically caused by LDL receptor mutations impairing LDL clearance.', 3),
('f0000000-0000-0000-0000-000000000044', 'D', 'Nephrotic syndrome', false, 'Ruled out because although nephrotic syndrome can cause hyperlipidaemia, there is no evidence of proteinuria or oedema described, and the tendon xanthomata and strong family history point specifically to a genetic lipid disorder.', 4),
('f0000000-0000-0000-0000-000000000044', 'E', 'Hypothyroidism', false, 'Ruled out because although hypothyroidism can raise cholesterol, it would not cause tendon xanthomata, and there is no other evidence of thyroid dysfunction described.', 5),
('f0000000-0000-0000-0000-000000000045', 'A', 'Fibrate therapy', false, 'Ruled out because fibrates are not first-line for primary prevention of cardiovascular disease based on elevated LDL/general cardiovascular risk; they are used mainly for severe hypertriglyceridaemia.', 1),
('f0000000-0000-0000-0000-000000000045', 'B', 'Ezetimibe monotherapy as first-line treatment', false, 'Ruled out because ezetimibe is used as an add-on when statins are not tolerated or insufficient, not as first-line monotherapy for primary prevention.', 2),
('f0000000-0000-0000-0000-000000000045', 'C', 'No pharmacological treatment, lifestyle advice alone', false, 'Ruled out because a QRISK score of 22% is well above the 10% threshold at which statin therapy is recommended in addition to lifestyle measures, not instead of them.', 3),
('f0000000-0000-0000-0000-000000000045', 'D', 'Atorvastatin 20mg', true, 'Correct. For primary prevention of cardiovascular disease in a patient with a 10-year QRISK score of 10% or above (here, 22%), a statin (commonly atorvastatin 20mg) is recommended first-line, alongside lifestyle advice, to reduce future cardiovascular risk.', 4),
('f0000000-0000-0000-0000-000000000045', 'E', 'PCSK9 inhibitor', false, 'Ruled out because PCSK9 inhibitors are reserved for patients with familial hypercholesterolaemia or those who remain at high risk despite maximally tolerated statin and ezetimibe therapy, not as first-line treatment for standard primary prevention.', 5),
('f0000000-0000-0000-0000-000000000046', 'A', 'Stop the statin and investigate further', true, 'Correct. Significant muscle symptoms with a markedly elevated creatine kinase in a patient on a statin indicates statin-induced myopathy (with risk of progressing to rhabdomyolysis); the statin should be stopped and the patient investigated and monitored, with hydration to protect renal function if CK is very high.', 1),
('f0000000-0000-0000-0000-000000000046', 'B', 'Continue the statin at the same dose and monitor', false, 'Ruled out because continuing a statin causing significant myopathy with markedly elevated CK risks progression to rhabdomyolysis and acute kidney injury; it should be stopped.', 2),
('f0000000-0000-0000-0000-000000000046', 'C', 'Increase the statin dose to compensate for reduced effectiveness', false, 'Ruled out because increasing the dose would worsen the myopathy, not address it; the priority is stopping the causative drug.', 3),
('f0000000-0000-0000-0000-000000000046', 'D', 'Switch immediately to a different statin at an equivalent dose without stopping first', false, 'Ruled out because with a markedly elevated CK indicating significant myopathy/rhabdomyolysis risk, the statin should be stopped first and the patient allowed to recover before cautiously considering rechallenge with an alternative statin or lower dose later.', 4),
('f0000000-0000-0000-0000-000000000046', 'E', 'Reassure the patient that this is a normal statin side effect requiring no action', false, 'Ruled out because a CK 15 times the upper limit of normal reflects significant muscle damage and risk of rhabdomyolysis, requiring active management, not reassurance alone.', 5),
('f0000000-0000-0000-0000-000000000047', 'A', 'Diabetic ketoacidosis', false, 'Ruled out because although DKA can cause abdominal pain, it would be accompanied by ketosis and acidosis, and would not explain the markedly raised amylase, which specifically points to pancreatitis.', 1),
('f0000000-0000-0000-0000-000000000047', 'B', 'Hypertriglyceridaemia-induced acute pancreatitis', true, 'Correct. Markedly elevated triglycerides (typically above 11.3 mmol/L, and especially at this severity) is a recognised cause of acute pancreatitis, thought to result from free fatty acid release from triglyceride hydrolysis causing direct pancreatic toxicity.', 2),
('f0000000-0000-0000-0000-000000000047', 'C', 'Cholecystitis', false, 'Ruled out because although gallstones are a common cause of pancreatitis, there is no mention of gallstone disease here, and the markedly elevated triglycerides point specifically to a hypertriglyceridaemia-induced mechanism.', 3),
('f0000000-0000-0000-0000-000000000047', 'D', 'Diabetic gastroparesis', false, 'Ruled out because gastroparesis causes chronic bloating, nausea and early satiety rather than acute severe pain with a markedly raised amylase, which indicates pancreatitis.', 4),
('f0000000-0000-0000-0000-000000000047', 'E', 'Mesenteric ischaemia', false, 'Ruled out because mesenteric ischaemia does not typically cause this degree of amylase elevation, and the markedly raised triglycerides provide a clear alternative explanation via pancreatitis.', 5),
('f0000000-0000-0000-0000-000000000048', 'A', 'Switch to a fibrate instead of a statin', false, 'Ruled out because fibrates primarily lower triglycerides and are not the preferred choice for further LDL reduction when a statin is already tolerated well; ezetimibe as an add-on is more appropriate.', 1),
('f0000000-0000-0000-0000-000000000048', 'B', 'Stop the statin, as target has nearly been reached', false, 'Ruled out because his LDL remains above target and he tolerates the statin well; stopping it would worsen control rather than help achieve target.', 2),
('f0000000-0000-0000-0000-000000000048', 'C', 'Add high-dose niacin', false, 'Ruled out because niacin is not commonly used or recommended due to a poor side-effect profile and lack of demonstrated outcome benefit when added to statin therapy in this context.', 3),
('f0000000-0000-0000-0000-000000000048', 'D', 'Add ezetimibe', true, 'Correct. When LDL cholesterol remains above target despite maximally tolerated statin therapy, ezetimibe (which reduces intestinal cholesterol absorption) is the recommended first add-on therapy to further lower LDL cholesterol.', 4),
('f0000000-0000-0000-0000-000000000048', 'E', 'PCSK9 inhibitor as the immediate next step', false, 'Ruled out because PCSK9 inhibitors are typically reserved for patients whose LDL remains above target despite statin plus ezetimibe, not as the first add-on before ezetimibe has been tried.', 5),
('f0000000-0000-0000-0000-000000000049', 'A', 'Start a statin immediately without further assessment', false, 'Ruled out because identifying and addressing any secondary or reversible cause is appropriate first, alongside standard cardiovascular risk assessment, rather than jumping straight to pharmacological treatment without this context.', 1),
('f0000000-0000-0000-0000-000000000049', 'B', 'Reassure her that this is a normal finding requiring no action', false, 'Ruled out because a total cholesterol of 7.1 mmol/L is significantly elevated and warrants further assessment, not reassurance without any evaluation.', 2),
('f0000000-0000-0000-0000-000000000049', 'C', 'Screen for secondary causes of hyperlipidaemia (e.g. repeat thyroid function, renal and liver function, HbA1c)', true, 'Correct. In a patient with newly identified hyperlipidaemia and no strong family history or classic FH features, screening for secondary causes (uncontrolled hypothyroidism, diabetes, renal or liver disease, excess alcohol) is an appropriate first step, since her hypothyroidism, though reported as controlled, and other reversible causes should be excluded or optimised before attributing the lipid abnormality purely to primary hyperlipidaemia.', 3),
('f0000000-0000-0000-0000-000000000049', 'D', 'Arrange genetic testing for familial hypercholesterolaemia as the first step', false, 'Ruled out because genetic testing is reserved for cases with a clinical suspicion of FH (e.g. very high LDL, tendon xanthomata, strong family history), none of which are present here; screening for secondary causes is more appropriate first.', 4),
('f0000000-0000-0000-0000-000000000049', 'E', 'Refer directly for bariatric surgery assessment', false, 'Ruled out because she has a healthy weight, making bariatric surgery irrelevant to her lipid abnormality; this option does not address the actual clinical scenario.', 5),
('f0000000-0000-0000-0000-000000000050', 'A', 'Direct nephrotoxicity from clarithromycin', false, 'Ruled out because the mechanism here relates to a pharmacokinetic drug interaction increasing statin exposure and causing myopathy, not direct nephrotoxicity from clarithromycin itself.', 1),
('f0000000-0000-0000-0000-000000000050', 'B', 'An idiosyncratic allergic reaction to clarithromycin', false, 'Ruled out because an allergic reaction would not specifically raise creatine kinase in this pattern; the clinical and pharmacological context points to a known drug-drug interaction via CYP3A4 inhibition.', 2),
('f0000000-0000-0000-0000-000000000050', 'C', 'Reduced renal clearance of clarithromycin', false, $x$Ruled out because this does not explain the muscle toxicity; the relevant interaction is clarithromycin's effect on statin metabolism, not the reverse.$x$, 3),
('f0000000-0000-0000-0000-000000000050', 'D', 'Coincidental, unrelated viral myositis', false, 'Ruled out because the clear temporal relationship to starting a known interacting drug combination makes a drug interaction far more likely than a coincidental unrelated cause.', 4),
('f0000000-0000-0000-0000-000000000050', 'E', 'CYP3A4 inhibition by clarithromycin increasing statin plasma concentration', true, 'Correct. Clarithromycin is a potent inhibitor of the CYP3A4 enzyme responsible for metabolising many statins (e.g. simvastatin, atorvastatin); co-administration significantly raises statin plasma levels, increasing the risk of myopathy and rhabdomyolysis.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f0000000-0000-0000-0000-000000000001', 'An HbA1c of 58 mmol/mol confirms a diagnosis of type 2 diabetes (threshold 48 mmol/mol) and indicates a level requiring pharmacological treatment.', 1),
('f0000000-0000-0000-0000-000000000001', $x$Metformin's favourable side-effect profile (no hypoglycaemia, weight-neutral or weight-reducing) makes it the standard first-line choice in the absence of contraindications.$x$, 2),
('f0000000-0000-0000-0000-000000000001', 'Absence of symptoms or metabolic decompensation (e.g. no ketosis, no marked hyperglycaemia) means oral therapy, not insulin, is appropriate to start.', 3),
('f0000000-0000-0000-0000-000000000002', 'An eGFR below 30 mL/min/1.73m2 is the accepted threshold at which metformin must be stopped due to accumulation risk.', 1),
('f0000000-0000-0000-0000-000000000002', 'Metformin is renally cleared, so reduced renal function directly raises plasma levels and the risk of lactic acidosis.', 2),
('f0000000-0000-0000-0000-000000000002', $x$Between eGFR 30-45, dose reduction (rather than complete cessation) is appropriate, distinguishing this patient's more severe impairment from that intermediate category.$x$, 3),
('f0000000-0000-0000-0000-000000000003', 'Established cardiovascular disease is a key factor favouring an SGLT2 inhibitor (or GLP-1 receptor agonist) as the preferred second-line add-on, per outcome trial evidence.', 1),
('f0000000-0000-0000-0000-000000000003', 'SGLT2 inhibitors reduce heart failure hospitalisation as well as atherosclerotic cardiovascular events, a dual benefit not shared by sulfonylureas or DPP-4 inhibitors.', 2),
('f0000000-0000-0000-0000-000000000003', $x$Pioglitazone's fluid-retaining, heart-failure-worsening properties make it specifically inappropriate here, despite being an effective glucose-lowering agent in other contexts.$x$, 3),
('f0000000-0000-0000-0000-000000000004', 'The glucose-dependent nature of GLP-1-stimulated insulin release (unlike sulfonylureas) explains the low intrinsic hypoglycaemia risk of this drug class.', 1),
('f0000000-0000-0000-0000-000000000004', 'Delayed gastric emptying and central appetite suppression underlie the weight-loss benefit distinctive to GLP-1 receptor agonists among diabetes therapies.', 2),
('f0000000-0000-0000-0000-000000000004', 'Suppression of glucagon secretion contributes an additional glucose-lowering mechanism distinct from the insulin-secretion effect alone.', 3),
('f0000000-0000-0000-0000-000000000005', 'A lean body habitus with rapid symptom onset is atypical for type 2 diabetes and raises suspicion for type 1 (or latent autoimmune diabetes of adulthood).', 1),
('f0000000-0000-0000-0000-000000000005', 'A personal or family history of other autoimmune conditions (e.g. autoimmune thyroid disease) increases the pretest probability of autoimmune type 1 diabetes.', 2),
('f0000000-0000-0000-0000-000000000005', 'Positive islet autoantibodies (anti-GAD, anti-IA2, anti-ZnT8) confirm an autoimmune aetiology and typically prompt earlier initiation of insulin therapy.', 3),
('f0000000-0000-0000-0000-000000000006', 'Confirmed microalbuminuria (ACR 3-30 mg/mmol) in a diabetic patient signals early diabetic nephropathy, warranting renoprotective treatment even with normal renal function and blood pressure.', 1),
('f0000000-0000-0000-0000-000000000006', 'ACE inhibitors/ARBs reduce intraglomerular pressure and proteinuria through mechanisms independent of their blood-pressure-lowering effect, which is why they are specifically preferred over other antihypertensives here.', 2),
('f0000000-0000-0000-0000-000000000006', 'A typical clinical context (longstanding diabetes with gradual-onset albuminuria) generally allows diagnosis and treatment without biopsy, reserved for atypical features (e.g. rapid decline, haematuria, short diabetes duration).', 3),
('f0000000-0000-0000-0000-000000000007', 'Sulfonylureas stimulate insulin release independent of glucose level, giving them a relatively high intrinsic risk of hypoglycaemia compared with agents like metformin or DPP-4 inhibitors.', 1),
('f0000000-0000-0000-0000-000000000007', 'Recurrent, biochemically confirmed hypoglycaemia (glucose <3.0 mmol/L with symptoms) warrants active dose reduction, not simple reassurance, particularly in older patients at higher risk of falls and cognitive sequelae.', 2),
('f0000000-0000-0000-0000-000000000007', $x$Glycaemic targets are typically relaxed in older or frail patients to reduce hypoglycaemia risk, which is directly relevant to reviewing this patient's overall treatment plan.$x$, 3),
('f0000000-0000-0000-0000-000000000008', 'Diabetic retinopathy is often asymptomatic until advanced, making structured annual screening (rather than waiting for symptoms) essential to detect treatable early disease.', 1),
('f0000000-0000-0000-0000-000000000008', 'Standard annual diabetic review also includes foot examination, urine ACR, renal function, blood pressure and lipid profile -- targeted, evidence-based surveillance for known complication patterns.', 2),
('f0000000-0000-0000-0000-000000000008', 'General screening tests unrelated to diabetes-specific complications (e.g. colonoscopy, brain MRI) are not part of this structured programme.', 3),
('f0000000-0000-0000-0000-000000000009', 'The triad of hyperglycaemia, ketosis (blood ketones >3 mmol/L) and acidosis (pH <7.3 or bicarbonate <15 mmol/L) defines diabetic ketoacidosis.', 1),
('f0000000-0000-0000-0000-000000000009', 'IV fluids address dehydration from osmotic diuresis, while insulin is required to switch off hepatic ketogenesis, the process driving the acidosis.', 2),
('f0000000-0000-0000-0000-000000000009', 'Potassium must be closely monitored and replaced during treatment, as insulin drives potassium into cells and can precipitate dangerous hypokalaemia despite normal or high initial levels.', 3),
('f0000000-0000-0000-0000-000000000010', 'HHS is characterised by very high glucose and osmolality with minimal ketosis and near-normal pH, distinguishing it from DKA (significant ketosis and acidosis).', 1),
('f0000000-0000-0000-0000-000000000010', 'HHS typically occurs in older patients with type 2 diabetes, often with a preceding illness or dehydration, whereas DKA is more classically associated with type 1 diabetes.', 2),
('f0000000-0000-0000-0000-000000000010', 'Management of HHS emphasises slower, more cautious fluid replacement (given the risk of rapid osmotic shifts in often frail, elderly patients) compared with the more standardised DKA protocol.', 3),
('f0000000-0000-0000-0000-000000000011', 'Insulin therapy in DKA shifts potassium into cells, meaning serum potassium typically falls during treatment even if it started normal or high, requiring proactive monitoring and replacement.', 1),
('f0000000-0000-0000-0000-000000000011', 'ECG changes (flattened T waves) reflect the cardiac risk of hypokalaemia, reinforcing the need for prompt potassium replacement and monitoring rather than watchful waiting.', 2),
('f0000000-0000-0000-0000-000000000011', 'Insulin must be continued (not stopped) despite the hypokalaemia, since it remains essential to switch off ketogenesis; the electrolyte disturbance is managed alongside, not by halting, insulin therapy.', 3),
('f0000000-0000-0000-0000-000000000012', 'Ability to safely swallow and full consciousness determines that oral (rather than parenteral) treatment is appropriate and preferred.', 1),
('f0000000-0000-0000-0000-000000000012', '15-20g of fast-acting carbohydrate is the standard treatment quantity, followed by a recheck at 15 minutes to confirm response before considering further action.', 2),
('f0000000-0000-0000-0000-000000000012', 'Post-exercise hypoglycaemia, sometimes delayed by up to several hours, is a recognised risk in patients on insulin therapy, relevant to future dose or activity planning, but does not change the acute treatment approach.', 3),
('f0000000-0000-0000-0000-000000000013', $x$SGLT2 inhibitors cause glucosuria, which can mask the degree of hyperglycaemia that would normally accompany significant ketoacidosis, producing the 'euglycaemic' pattern.$x$, 1),
('f0000000-0000-0000-0000-000000000013', 'Significant ketosis (>3 mmol/L) and acidosis (pH <7.3) remain diagnostic of DKA regardless of the glucose level, so a near-normal or only mildly elevated glucose should not be reassuring in a patient on an SGLT2 inhibitor who is unwell.', 2),
('f0000000-0000-0000-0000-000000000013', 'Management still follows standard DKA principles (IV fluids, fixed-rate insulin infusion with concurrent glucose to prevent hypoglycaemia, and stopping the SGLT2 inhibitor).', 3),
('f0000000-0000-0000-0000-000000000014', 'Reduced consciousness in hypoglycaemia is an indication for parenteral (IM glucagon or IV glucose), not oral, treatment, due to aspiration risk.', 1),
('f0000000-0000-0000-0000-000000000014', 'IM glucagon is specifically designed for use by trained family members/carers in the community when IV access is unavailable, making it the appropriate immediate step here.', 2),
('f0000000-0000-0000-0000-000000000014', 'Severe hypoglycaemia requires urgent treatment rather than watchful waiting, given the risk of seizure or prolonged neuroglycopenia causing lasting harm.', 3),
('f0000000-0000-0000-0000-000000000015', 'Resolution of DKA is defined biochemically (ketones <0.6 mmol/L, pH >7.3, or bicarbonate >18 mmol/L), not simply by an improving glucose level, and guides the timing of stopping IV insulin.', 1),
('f0000000-0000-0000-0000-000000000015', 'An overlap period between IV and subcutaneous insulin is essential because IV insulin has a very short half-life once the infusion stops, and subcutaneous insulin takes time to establish effective levels.', 2),
('f0000000-0000-0000-0000-000000000015', 'The ability to eat and drink normally is a practical prerequisite for safely transitioning back to a subcutaneous insulin regimen.', 3),
('f0000000-0000-0000-0000-000000000016', $x$Thyroid eye disease (proptosis, lid lag, periorbital signs) is specific to Graves' disease among the causes of hyperthyroidism.$x$, 1),
('f0000000-0000-0000-0000-000000000016', $x$A diffusely enlarged, smooth (rather than nodular) goitre supports Graves' disease over toxic multinodular goitre or toxic adenoma.$x$, 2),
('f0000000-0000-0000-0000-000000000016', $x$Suppressed TSH with markedly raised free T4 confirms primary hyperthyroidism, with the additional eye signs specifically pointing to an autoimmune (Graves') aetiology.$x$, 3),
('f0000000-0000-0000-0000-000000000017', 'Thyroid storm is precipitated by triggers such as infection, surgery, or trauma in a patient with poorly controlled hyperthyroidism, exactly the scenario described here.', 1),
('f0000000-0000-0000-0000-000000000017', 'Fever, marked tachycardia, agitation/confusion and cardiovascular compromise together define the severity criteria for thyroid storm, distinguishing it from simple uncontrolled hyperthyroidism.', 2),
('f0000000-0000-0000-0000-000000000017', 'Beta-blockade (e.g. propranolol) is used to control the adrenergic symptoms (tachycardia, agitation) while antithyroid drugs address the underlying excess hormone production.', 3),
('f0000000-0000-0000-0000-000000000018', 'A raised TSH with low free T4 confirms primary hypothyroidism, the underlying biochemical abnormality.', 1),
('f0000000-0000-0000-0000-000000000018', $x$Strongly positive anti-TPO antibodies are the hallmark of autoimmune (Hashimoto's) thyroiditis, distinguishing it from other causes of hypothyroidism.$x$, 2),
('f0000000-0000-0000-0000-000000000018', $x$A gradual, insidious symptom onset over months is typical of Hashimoto's thyroiditis, in contrast to the acute painful presentation of subacute thyroiditis.$x$, 3),
('f0000000-0000-0000-0000-000000000019', 'Sonographic features such as hypoechogenicity, irregular margins, and microcalcifications raise suspicion for thyroid malignancy and determine the need for biopsy.', 1),
('f0000000-0000-0000-0000-000000000019', $x$A normal TSH means the nodule is unlikely to be a hyperfunctioning ('hot') nodule, for which radioiodine scanning would otherwise be a reasonable next step.$x$, 2),
('f0000000-0000-0000-0000-000000000019', 'Fine needle aspiration cytology is the standard, minimally invasive first investigation for a suspicious thyroid nodule, guiding whether surgery is needed.', 3),
('f0000000-0000-0000-0000-000000000020', 'Onset within the first 12 months postpartum is the defining epidemiological clue for postpartum thyroiditis.', 1),
('f0000000-0000-0000-0000-000000000020', $x$Low radioiodine uptake during the thyrotoxic phase reflects a destructive process releasing preformed hormone, distinguishing it from Graves' disease (high uptake, active synthesis).$x$, 2),
('f0000000-0000-0000-0000-000000000020', 'Postpartum thyroiditis classically progresses through a thyrotoxic phase, then a hypothyroid phase, before resolving in most women, informing counselling and follow-up.', 3),
('f0000000-0000-0000-0000-000000000021', 'Divalent cations (calcium, iron) are classic culprits for reduced levothyroxine absorption when co-administered, due to chelation in the gut.', 1),
('f0000000-0000-0000-0000-000000000021', 'A rise in TSH shortly after starting a new medication in an otherwise stable patient should prompt review of concurrent medications for absorption-interfering agents before assuming a change in underlying thyroid status.', 2),
('f0000000-0000-0000-0000-000000000021', 'Advising patients to separate levothyroxine from calcium/iron supplements by several hours is a standard practical counselling point to prevent this interaction.', 3),
('f0000000-0000-0000-0000-000000000022', 'Rapid growth over weeks, rather than the typically slow growth of differentiated thyroid cancers, is a red flag for anaplastic carcinoma.', 1),
('f0000000-0000-0000-0000-000000000022', 'Local invasive features (hoarseness from recurrent laryngeal nerve palsy, dysphagia, fixed lymphadenopathy) reflect aggressive local spread, atypical for well-differentiated thyroid cancers.', 2),
('f0000000-0000-0000-0000-000000000022', 'Older age at presentation is typical for anaplastic thyroid carcinoma, which usually arises in patients over 60, often from a pre-existing differentiated cancer.', 3),
('f0000000-0000-0000-0000-000000000023', 'Progressive enlargement of the hands, feet and facial features (rather than generalised weight gain) is a specific clue to excess growth hormone.', 1),
('f0000000-0000-0000-0000-000000000023', 'Failure of growth hormone to suppress below a defined threshold during an oral glucose tolerance test is the key diagnostic biochemical test for acromegaly.', 2),
('f0000000-0000-0000-0000-000000000023', 'New headaches suggest a mass effect from a pituitary adenoma, prompting further imaging (pituitary MRI) alongside the biochemical workup.', 3),
('f0000000-0000-0000-0000-000000000024', 'Sudden severe headache in a patient with a known pituitary adenoma should immediately raise suspicion of pituitary apoplexy.', 1),
('f0000000-0000-0000-0000-000000000024', 'Ophthalmoplegia (particularly third nerve palsy) reflects compression of structures in the adjacent cavernous sinus by the expanding, haemorrhagic pituitary mass.', 2),
('f0000000-0000-0000-0000-000000000024', 'Hypotension reflects acute secondary adrenal insufficiency from sudden loss of ACTH secretion, requiring urgent hydrocortisone alongside neurosurgical assessment.', 3),
('f0000000-0000-0000-0000-000000000025', 'Prolactinomas are unique among pituitary adenomas in that they are first-line treated medically (dopamine agonists), rather than surgically, distinguishing their management from other functioning pituitary tumours.', 1),
('f0000000-0000-0000-0000-000000000025', 'Markedly elevated prolactin (often correlating with tumour size) alongside a pituitary lesion on imaging supports the diagnosis, having excluded pregnancy and hypothyroidism (both of which can also raise prolactin) as the cause.', 2),
('f0000000-0000-0000-0000-000000000025', 'Dopamine agonists work by directly inhibiting prolactin secretion via dopamine D2 receptors on lactotroph cells, and typically shrink the tumour as an added benefit.', 3),
('f0000000-0000-0000-0000-000000000026', $x$A history of severe postpartum haemorrhage is the classic precipitant for Sheehan syndrome, due to the pituitary's vulnerability to ischaemia during pregnancy-related hypotension.$x$, 1),
('f0000000-0000-0000-0000-000000000026', 'Failure to lactate (from loss of prolactin) is a distinctive early clue, distinguishing this from other postpartum endocrine disorders.', 2),
('f0000000-0000-0000-0000-000000000026', 'Multiple pituitary hormone deficiencies (gonadotrophins causing amenorrhoea, TSH causing hypothyroid symptoms) developing together reflect global pituitary damage, rather than an isolated single-axis problem.', 3),
('f0000000-0000-0000-0000-000000000027', 'Euvolaemic hyponatraemia with inappropriately concentrated urine (rather than maximally dilute urine) is the hallmark of SIADH.', 1),
('f0000000-0000-0000-0000-000000000027', 'Small cell lung cancer is a classic cause of ectopic ADH secretion, causing paraneoplastic SIADH.', 2),
('f0000000-0000-0000-0000-000000000027', $x$Distinguishing euvolaemic (SIADH), hypovolaemic (e.g. Addison's, diuretics), and hypervolaemic (e.g. heart failure) causes of hyponatraemia is essential, as management differs substantially between them.$x$, 3),
('f0000000-0000-0000-0000-000000000028', 'Polyuria with inappropriately dilute urine, in the context of rising serum sodium, indicates a failure to concentrate urine appropriately -- the hallmark of diabetes insipidus.', 1),
('f0000000-0000-0000-0000-000000000028', 'Pituitary/hypothalamic surgery is a recognised cause of cranial diabetes insipidus through disruption of ADH synthesis or release, distinct from nephrogenic DI (renal resistance to ADH).', 2),
('f0000000-0000-0000-0000-000000000028', $x$Desmopressin (a synthetic ADH analogue) is the standard treatment for cranial diabetes insipidus, working because the defect is at the level of hormone production, not the kidney's response to it.$x$, 3),
('f0000000-0000-0000-0000-000000000029', 'Bitemporal hemianopia is a classic, specific sign of chiasmal compression, most commonly from a pituitary macroadenoma expanding upward from the sella turcica.', 1),
('f0000000-0000-0000-0000-000000000029', 'The nasal retinal fibres (which decussate at the chiasm and carry temporal field information) are the ones affected by midline chiasmal compression, explaining the bitemporal (rather than homonymous) pattern.', 2),
('f0000000-0000-0000-0000-000000000029', 'Associated hypopituitarism (reduced libido, erectile dysfunction from gonadotrophin deficiency) reflects compression/destruction of normal pituitary tissue by the expanding mass, supporting the pituitary origin of the visual defect.', 3),
('f0000000-0000-0000-0000-000000000030', 'Hyperpigmentation specifically indicates primary (not secondary) adrenal insufficiency, as it reflects markedly elevated ACTH (and its precursor, which shares melanocyte-stimulating activity) in the absence of cortisol negative feedback.', 1),
('f0000000-0000-0000-0000-000000000030', 'Combined hyponatraemia and hyperkalaemia reflect both glucocorticoid and mineralocorticoid deficiency, both of which are lost in primary adrenal failure but largely preserved in secondary (pituitary) adrenal insufficiency.', 2),
('f0000000-0000-0000-0000-000000000030', 'A low morning cortisol in the context of these clinical and electrolyte features supports the diagnosis, typically confirmed further with a short Synacthen (ACTH stimulation) test.', 3),
('f0000000-0000-0000-0000-000000000031', 'Intercurrent illness (here, gastroenteritis) is a classic precipitant of adrenal crisis in patients with adrenal insufficiency, who cannot increase endogenous cortisol production appropriately.', 1),
('f0000000-0000-0000-0000-000000000031', 'Inability to take or absorb oral medication (from vomiting) means parenteral steroid replacement is mandatory, not an increased oral dose.', 2),
('f0000000-0000-0000-0000-000000000031', 'Adrenal crisis is immediately life-threatening; treatment must not be delayed for confirmatory testing when there is a known diagnosis and a compatible clinical picture.', 3),
('f0000000-0000-0000-0000-000000000032', 'Prolonged exogenous glucocorticoid use suppresses ACTH secretion through negative feedback, leading to adrenal cortex atrophy over time -- this is why steroids must be weaned, not stopped abruptly, after long-term use.', 1),
('f0000000-0000-0000-0000-000000000032', 'The physiological stress of surgery normally requires a marked increase in cortisol output, which a suppressed HPA axis cannot provide, precipitating crisis.', 2),
('f0000000-0000-0000-0000-000000000032', 'A blunted response to ACTH (Synacthen) stimulation confirms inadequate adrenal reserve, consistent with secondary adrenal insufficiency from HPA axis suppression rather than a primary adrenal problem.', 3),
('f0000000-0000-0000-0000-000000000033', $x$Once Cushing's syndrome is biochemically confirmed, measuring plasma ACTH is the pivotal next step, as it separates ACTH-dependent causes (pituitary adenoma, ectopic ACTH) from ACTH-independent causes (adrenal adenoma/carcinoma).$x$, 1),
('f0000000-0000-0000-0000-000000000033', 'A suppressed ACTH would point to an adrenal source (autonomous cortisol production suppressing pituitary ACTH), directing subsequent adrenal imaging.', 2),
('f0000000-0000-0000-0000-000000000033', 'A normal or raised ACTH would point to a pituitary or ectopic source, directing subsequent pituitary MRI and/or high-dose dexamethasone suppression testing to differentiate the two.', 3),
('f0000000-0000-0000-0000-000000000034', 'A suppressed renin alongside raised aldosterone (high aldosterone:renin ratio) is the biochemical hallmark of primary hyperaldosteronism, distinguishing it from secondary causes where both are elevated together.', 1),
('f0000000-0000-0000-0000-000000000034', 'Resistant hypertension with unprovoked or diuretic-induced hypokalaemia should prompt screening for primary hyperaldosteronism as a treatable cause.', 2),
('f0000000-0000-0000-0000-000000000034', 'Further investigation typically includes adrenal CT and, in some cases, adrenal vein sampling to distinguish a unilateral adenoma (surgically curable) from bilateral adrenal hyperplasia (managed medically with a mineralocorticoid receptor antagonist).', 3),
('f0000000-0000-0000-0000-000000000035', 'The classic triad of episodic headache, palpitations and sweating, with markedly elevated blood pressure during attacks and normal findings between episodes, is highly suggestive of phaeochromocytoma.', 1),
('f0000000-0000-0000-0000-000000000035', 'Elevated 24-hour urinary (or plasma) metanephrines provide biochemical confirmation of catecholamine excess, distinguishing this from other causes of paroxysmal symptoms such as panic disorder.', 2),
('f0000000-0000-0000-0000-000000000035', 'Alpha-blockade must be established before beta-blockade or surgery in phaeochromocytoma management, as beta-blockade alone can precipitate a hypertensive crisis from unopposed alpha-adrenergic vasoconstriction.', 3),
('f0000000-0000-0000-0000-000000000036', 'Ambiguous genitalia in a genetically female infant reflects in-utero virilisation from excess adrenal androgen production, a hallmark of 21-hydroxylase deficiency.', 1),
('f0000000-0000-0000-0000-000000000036', 'The salt-wasting crisis (hyponatraemia, hyperkalaemia, hypovolaemia) reflects combined cortisol and aldosterone deficiency, as 21-hydroxylase is required for both pathways.', 2),
('f0000000-0000-0000-0000-000000000036', 'Markedly elevated 17-hydroxyprogesterone (the substrate that accumulates proximal to the enzyme block) is the specific diagnostic biochemical marker for 21-hydroxylase deficiency.', 3),
('f0000000-0000-0000-0000-000000000037', 'An inappropriately raised PTH in the presence of hypercalcaemia (rather than the expected suppression) is the key finding pointing to primary hyperparathyroidism.', 1),
('f0000000-0000-0000-0000-000000000037', 'Malignancy-associated hypercalcaemia typically suppresses PTH, providing a useful biochemical discriminator from primary hyperparathyroidism.', 2),
('f0000000-0000-0000-0000-000000000037', 'Normal (rather than low) 24-hour urinary calcium excretion helps distinguish primary hyperparathyroidism from familial hypocalciuric hypercalcaemia, which can otherwise mimic it biochemically.', 3),
('f0000000-0000-0000-0000-000000000038', 'Low calcium and phosphate together with a raised alkaline phosphatase reflects the defective bone mineralisation characteristic of osteomalacia, distinguishing it biochemically from osteoporosis (normal biochemistry).', 1),
('f0000000-0000-0000-0000-000000000038', 'Proximal myopathy causing a waddling gait is a classic clinical feature of vitamin D deficiency/osteomalacia, reflecting the muscle effects of hypovitaminosis D.', 2),
('f0000000-0000-0000-0000-000000000038', 'Risk factors for reduced sun exposure (housebound status, darker skin pigmentation, cultural dress covering skin) are important contextual clues pointing towards vitamin D deficiency as the underlying cause.', 3),
('f0000000-0000-0000-0000-000000000039', $x$An isolated raised alkaline phosphatase with otherwise normal calcium, phosphate and liver function is a classic biochemical pattern of Paget's disease of bone.$x$, 1),
('f0000000-0000-0000-0000-000000000039', $x$Localised bone pain and deformity (e.g. bowing, increasing skull size) reflect the disorganised, excessive bone turnover characteristic of Paget's disease.$x$, 2),
('f0000000-0000-0000-0000-000000000039', $x$The mixed lytic and sclerotic radiographic appearance, often with cortical thickening, is a distinctive imaging feature helping distinguish Paget's disease from metastatic bone disease or other metabolic bone disorders.$x$, 3),
('f0000000-0000-0000-0000-000000000040', 'Reduced renal 1-alpha-hydroxylase activity in CKD impairs activation of vitamin D, reducing intestinal calcium absorption and contributing to hypocalcaemia.', 1),
('f0000000-0000-0000-0000-000000000040', 'Phosphate retention from reduced renal excretion in CKD directly lowers ionised calcium and stimulates PTH secretion, compounding the hypocalcaemia-driven parathyroid response.', 2),
('f0000000-0000-0000-0000-000000000040', 'The combination of low calcium, high phosphate and high PTH in a patient with significant CKD is the classic biochemical signature of secondary hyperparathyroidism (part of CKD-mineral and bone disorder), distinct from the hypercalcaemic pattern of primary or tertiary disease.', 3),
('f0000000-0000-0000-0000-000000000041', 'Severe hypercalcaemia (typically defined as corrected calcium above 3.5 mmol/L) with symptoms (confusion, polyuria) constitutes a medical emergency requiring prompt treatment.', 1),
('f0000000-0000-0000-0000-000000000041', 'IV rehydration comes first because malignant hypercalcaemia frequently causes significant volume depletion (from calcium-induced nephrogenic diabetes insipidus, vomiting, and reduced intake), which itself worsens hypercalcaemia by reducing renal calcium clearance.', 2),
('f0000000-0000-0000-0000-000000000041', 'IV bisphosphonates provide a more sustained reduction in calcium by inhibiting osteoclast-mediated bone resorption, but take 2-4 days to reach maximal effect, which is why rehydration is started immediately alongside it.', 3),
('f0000000-0000-0000-0000-000000000042', 'The parathyroid glands, located adjacent to or within the thyroid, are at risk of inadvertent damage or removal during thyroidectomy, making postoperative hypocalcaemia a well-recognised complication.', 1),
('f0000000-0000-0000-0000-000000000042', $x$Chvostek's sign (facial twitching on tapping the facial nerve) and Trousseau's sign (carpal spasm on cuff inflation) are classic clinical signs of neuromuscular hyperexcitability caused by hypocalcaemia.$x$, 2),
('f0000000-0000-0000-0000-000000000042', 'Timing shortly after thyroid surgery is the key contextual clue distinguishing post-surgical hypoparathyroidism from other causes of hypocalcaemia.', 3),
('f0000000-0000-0000-0000-000000000043', 'A DEXA T-score of -2.5 or lower is the WHO diagnostic threshold for osteoporosis, distinguishing it from osteopenia (-1.0 to -2.5) and normal bone density (above -1.0).', 1),
('f0000000-0000-0000-0000-000000000043', 'A low-trauma (fragility) fracture in this context is itself clinically diagnostic of osteoporosis, regardless of the T-score, reflecting compromised bone strength.', 2),
('f0000000-0000-0000-0000-000000000043', 'Normal calcium, phosphate and vitamin D help exclude osteomalacia and other metabolic bone diseases as a cause of reduced bone density, supporting primary osteoporosis as the diagnosis.', 3),
('f0000000-0000-0000-0000-000000000044', 'Tendon xanthomata (particularly over the Achilles tendons and extensor tendons of the hands) are a specific clinical sign of familial hypercholesterolaemia, reflecting cholesterol deposition from chronically very high LDL levels.', 1),
('f0000000-0000-0000-0000-000000000044', 'A family history of premature cardiovascular disease (typically before age 55 in men or 60 in women) is a key diagnostic clue supporting a genetic lipid disorder.', 2),
('f0000000-0000-0000-0000-000000000044', 'The degree of LDL elevation (often above 4.9 mmol/L in adults) in FH is substantially higher than typically seen in polygenic or lifestyle-related hypercholesterolaemia.', 3),
('f0000000-0000-0000-0000-000000000045', 'A QRISK3 score of 10% or higher is the threshold at which statin therapy is recommended for primary cardiovascular prevention.', 1),
('f0000000-0000-0000-0000-000000000045', 'Atorvastatin 20mg is the standard first-line statin and dose for primary prevention, reserving higher intensity statins for secondary prevention or higher-risk scenarios.', 2),
('f0000000-0000-0000-0000-000000000045', 'Lifestyle measures remain important alongside, not instead of, statin therapy once the risk threshold for pharmacological treatment is met.', 3),
('f0000000-0000-0000-0000-000000000046', 'A markedly elevated creatine kinase (many multiples of the upper limit of normal) with muscle symptoms indicates significant statin-induced myopathy, distinguishing it from the mild myalgia that can occur without significant CK rise.', 1),
('f0000000-0000-0000-0000-000000000046', 'Rhabdomyolysis is a recognised, serious complication of statin therapy, carrying a risk of acute kidney injury from myoglobin-induced renal tubular damage, which is why the statin must be stopped promptly.', 2),
('f0000000-0000-0000-0000-000000000046', 'After recovery, cautious rechallenge with a lower dose or an alternative statin (or non-statin lipid-lowering therapy) can be considered, but only once the acute myopathy has resolved.', 3),
('f0000000-0000-0000-0000-000000000047', 'Triglyceride levels above roughly 11.3 mmol/L carry a significant risk of precipitating acute pancreatitis, making this level (and higher) clinically important to recognise and treat urgently.', 1),
('f0000000-0000-0000-0000-000000000047', 'Poorly controlled diabetes is a common secondary contributor to severe hypertriglyceridaemia, alongside primary genetic lipid disorders, and should prompt review of glycaemic control as part of management.', 2),
('f0000000-0000-0000-0000-000000000047', 'Management of hypertriglyceridaemia-induced pancreatitis includes standard pancreatitis supportive care plus specific triglyceride-lowering measures (e.g. insulin infusion, fibrates once stable), distinguishing it from gallstone or alcohol-related pancreatitis.', 3),
('f0000000-0000-0000-0000-000000000048', $x$Ezetimibe is the standard first add-on to a maximally tolerated statin when LDL remains above target, working via a complementary mechanism (reduced intestinal cholesterol absorption) to the statin's reduced hepatic synthesis.$x$, 1),
('f0000000-0000-0000-0000-000000000048', 'PCSK9 inhibitors are reserved for patients who remain above target despite combined statin and ezetimibe therapy, reflecting a stepped treatment approach.', 2),
('f0000000-0000-0000-0000-000000000048', 'Good tolerance of the current statin (no muscle symptoms) supports continuing it and adding therapy, rather than switching agents.', 3),
('f0000000-0000-0000-0000-000000000049', 'Secondary causes of hyperlipidaemia (hypothyroidism, diabetes, renal disease, liver disease, alcohol excess, certain medications) should be actively considered and excluded or treated before attributing lipid abnormalities purely to a primary disorder.', 1),
('f0000000-0000-0000-0000-000000000049', 'Absence of a strong family history or physical signs of FH (such as tendon xanthomata) makes a secondary or polygenic cause more likely than familial hypercholesterolaemia in this context.', 2),
('f0000000-0000-0000-0000-000000000049', 'Confirming that her thyroid status is genuinely well controlled (rather than assuming from history alone) is directly relevant, as inadequately treated hypothyroidism is a recognised secondary cause of hyperlipidaemia.', 3),
('f0000000-0000-0000-0000-000000000050', 'Macrolide antibiotics (particularly clarithromycin and erythromycin) are well-recognised CYP3A4 inhibitors that significantly increase levels of CYP3A4-metabolised statins (simvastatin, atorvastatin), raising myopathy risk.', 1),
('f0000000-0000-0000-0000-000000000050', 'A clear temporal relationship between starting the interacting drug and developing muscle symptoms supports a pharmacokinetic drug interaction as the cause.', 2),
('f0000000-0000-0000-0000-000000000050', 'Awareness of this interaction should prompt temporary statin discontinuation or dose adjustment when a interacting antibiotic course is needed, or use of a non-interacting alternative (e.g. azithromycin, which is a weaker CYP3A4 inhibitor).', 3);
